// The MCP tools for everything the window does that server.mjs did not already cover (docs/ADR-028: anything the app can do, the MCP can do).
// Each tool is a thin call into the same core function the window's IPC channel calls (electron/core.cjs TABLE); mcp/parity.mjs says which tool answers which channel.
// Spend is gated with the named yes (governance.namedYes); the pod manager's own keys and settings are not (ADR-028, decision 6); the no-spend switch is never settable here.
import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { isAbsolute } from 'node:path'
import * as docs from './docs.mjs'

const obj = (properties = {}, required = []) => ({ type: 'object', properties, ...(required.length ? { required } : {}) })
const S = (description, extra = {}) => ({ type: 'string', description, ...extra })
const N = (description, extra = {}) => ({ type: 'integer', description, ...extra })
const B = (description) => ({ type: 'boolean', description })
const O = (description) => ({ type: 'object', description })

/** A patch over a configuration: objects (folders, env, required, mcp_http) merge by key, everything else replaces. `dry_run` (no-spend) is never taken from a patch. */
export function mergeConfig(base, patch) {
  if (patch && 'dry_run' in patch) throw Object.assign(new Error('The no-spend switch (dry_run) is not settable over MCP: it is the safety, set it in the app.'), { status: 400 })
  if (patch && patch.auto_publish && typeof patch.auto_publish === 'object') {   // docs/ADR-050: what Auto-publish does and where it sends is a person's choice, in the window
    const b = base.auto_publish || {}, v = patch.auto_publish, t = v.targets && typeof v.targets === 'object' ? v.targets : {}, bt = b.targets || {}
    if (v.generate && v.generate.colour_in && v.generate.colour_in !== (b.generate || {}).colour_in) throw Object.assign(new Error("403: Stating the colour of frames is a person's act: put the approver's name in the window"), { status: 403 })
    if (v.generate && v.generate.where === 'pod' && (b.generate || {}).where !== 'pod') throw Object.assign(new Error("403: Rendering on a pod spends money: put the approver's name in the window"), { status: 403 })
    if (Object.keys(t).some((k) => t[k] !== bt[k]) || ('slack' in v && v.slack !== (bt.slack === true))) throw Object.assign(new Error("403: Where Auto-publish sends is chosen in the window, by a person"), { status: 403 })
    if ((v.enabled !== undefined && v.enabled !== b.enabled && v.enabled !== false) || (v.dry_run === false && b.dry_run !== false) || (v.dry_run_first !== undefined && v.dry_run_first !== (b.dry_run_first !== false)) || ('standing' in v && JSON.stringify(v.standing ?? null) !== JSON.stringify(b.standing ?? null))) throw Object.assign(new Error('403: Auto-publish is turned on in the window, by a person'), { status: 403 })
  }
  const out = { ...base }
  for (const [k, v] of Object.entries(patch || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v) && base[k] && typeof base[k] === 'object' && !Array.isArray(base[k])) out[k] = { ...base[k], ...v }
    else out[k] = v
  }
  return out
}

/** The settings `set_settings` takes, by field. A value of null removes it. */
export const SETTING_FIELDS = ['runpod_api_key', 'anthropic_api_key', 'hf_token', 'runpod_s3_access_key', 'runpod_s3_secret_key', 'panama_aws_access_key', 'panama_aws_secret_key', 'panama_console_key', 'panama_bucket', 'panama_region', 'panama_profile', 'agent_named_yes_required', 'agent_spend_cap_usd', 'agent_shell_guard', 'chunked_runs']

const MAX_FILE = 2 * 1024 * 1024

export function appTools({ core, governance, text, json, plain = text }) {
  const { hf, wantedmodels, mounts, pods, volumes, settings, configio, panama, library, podpull, runflows, chunking, queue, imports, studio, images, git, repositories, remote, mcp } = core
  const yes = (args, what) => governance.namedYes(args, what)
  // Generate Outputs and Publish always act under a person's name, even when the named-yes setting is off (never guessed, never defaulted)
  const needsName = (args, items) => ((args.generate_outputs || args.publish || (items || []).some((i) => i && (i.generate_outputs || i.publish))) && !String(args.approved_by ?? '').trim() ? 'Generate Outputs and Publish act under a name: give approved_by, the name of the person who says yes (never guessed).' : null)
  const approved = obj({ approved_by: S('Who said yes to this spend. Only needed when the named-yes setting is on (set_settings agent_named_yes_required); never guessed.') })
  const absolutePath = (p, what) => { if (!p || !isAbsolute(p)) throw Object.assign(new Error(`${what} must be an absolute path`), { status: 400 }); return p }
  const target = { type: 'string', enum: ['local', 'pod'], default: 'local', description: 'local = staged on this PC; pod = staged on the network volume by a pod (a pod download may start a pod: approved_by (only when the named-yes setting is on))' }
  const volumes_job = { browse: (id, path) => podpull.browseVolume(id, path ? { path } : {}), erase: (id, keys, o) => podpull.eraseVolume(id, keys, o) }
  const pickPanama = (args) => (args.target === 'pod' ? podpull : panama)
  const summaryOf = (cfg) => { const p = mounts.payload(cfg); return { mode: p.mode, volume: cfg.network_volume_id || null, datacenter: cfg.data_center_id || null, image: cfg.image, idle_stop_minutes: cfg.idle_stop_minutes, apply_by_default: cfg.apply_by_default, folders: p.folders.map((r) => ({ key: r.key, local: r.local || null, on_pod: r.container })) } }

  const T = [
    // ---------- pods ----------
    { name: 'list_gpus', description: "The card menu with what RunPod has in stock and the on-demand price, for a datacenter (or the volume's, or anywhere): the table's cards, big ones included (explicit-only, ADR-026)", inputSchema: obj({ datacenter: S('Datacenter id (list_datacenters); omit for the configured volume\'s, else anywhere') }),
      run: async ({ datacenter }) => json(await pods.gpuMenu(undefined, datacenter || undefined)) },
    { name: 'get_volume_info', description: "The network volume a pod would use (the configured one, or the one named): size, datacenter, cost", inputSchema: obj({ volume_id: S('Volume ID; omit for the configured one') }),
      run: async ({ volume_id }) => json(await pods.volumeInfo(volume_id || undefined)) },
    { name: 'get_pod_config', description: "[folder_excludes ({ project, plates, comfy-shared, workflows: [patterns] }, ADR-011: per-folder exclusion defaults, relative to THAT folder's root, added to sync_exclude for that step only; a pod's own map replaces the Default's per key, an empty list clears the key for the pod; at most 100 per key and 300 in all) and sync_exclude_delete (a push with exclusions also removes what the patterns match on the volume, a guarded removal that still needs a named yes; default false) are part of the configuration.] [sync_exclude (a list of folder or file patterns a push leaves out, rsync semantics: `/X/` the top-level folder, `X/` folders anywhere, `X` anything named X) is part of the configuration (ADR-011): the pod's own list replaces the Default's; a run's `exclude` is added; default []; they only remove things from a push.] [render { where, kind, proxy_width, review_width, codecs, fps, pull, skip_existing, publish: { s3, slack } } is part of the configuration (ADR-048): how DPX sequences are rendered; `pull` (Sync the renders to this PC when done) defaults to OFF, `skip_existing` to ON, `publish` (what the Generate window pre-ticks for Publish to S3 / Post to Slack when done) to both off, and publishing needs the renders on this PC (pull on, or where local); they are preferences, a run still needs its own `publish` field and approved_by; an app-wide `outputs { hide_empty_folders }` (default true) is the starting choice of the Outputs window; default { auto, proxy, source, source, [prores422hq], auto, true }; no approver and no allow_partial are ever stored.] [auto_sync { enabled, pull, push, approved_by } is part of the configuration (ADR-046): Auto sync for each pod created under it; enabled: true needs approved_by, the named yes; default off, Pull on, Push off.] A pod's own configuration (the Default Configuration's shape, kept for recreate_pod), or null when it uses the Default Configuration", inputSchema: obj({ pod_id: S('Pod ID') }, ['pod_id']),
      run: async ({ pod_id }) => { await pods.get(pod_id); const c = pods.config(pod_id); return json({ pod_id, custom_config: !!c, config: c, note: c ? undefined : 'This pod uses the Default Configuration (get_configuration).' }) } },
    { name: 'set_pod_config', description: "[folder_excludes ({ project, plates, comfy-shared, workflows: [patterns] }, ADR-011: per-folder exclusion defaults, relative to THAT folder's root, added to sync_exclude for that step only; a pod's own map replaces the Default's per key, an empty list clears the key for the pod; at most 100 per key and 300 in all) and sync_exclude_delete (a push with exclusions also removes what the patterns match on the volume, a guarded removal that still needs a named yes; default false) are part of the configuration.] [sync_exclude (a list of folder or file patterns a push leaves out, rsync semantics: `/X/` the top-level folder, `X/` folders anywhere, `X` anything named X) is part of the configuration (ADR-011): the pod's own list replaces the Default's; a run's `exclude` is added; default []; they only remove things from a push.] [render { where, kind, proxy_width, review_width, codecs, fps, pull } is part of the configuration (ADR-048): how DPX sequences are rendered; default { auto, proxy, source, source, [prores422hq], auto, true }; no approver and no allow_partial are ever stored.] [auto_sync { enabled, pull, push, approved_by } is part of the configuration (ADR-046): Auto sync for each pod created under it; enabled: true needs approved_by, the named yes; default off, Pull on, Push off.] Change a pod's own configuration: a patch over its current one (or the Default Configuration), or reset it back to the default. It is kept for recreate_pod; most of it (volume, env, links, image) reaches a pod only when it is made, so pass recreate=true to apply it now (that makes a new pod: spends, approved_by (only when the named-yes setting is on)). dry_run is never settable.",
      inputSchema: obj({ pod_id: S('Pod ID'), patch: O('Fields to change, in the Default Configuration\'s shape (get_configuration); objects merge by key'), reset: B('Go back to the Default Configuration'), recreate: B('Then recreate the pod with it (spends)'), approved_by: approved.properties.approved_by }, ['pod_id']),
      run: async (args) => {
        await pods.get(args.pod_id)
        if (args.recreate) { const refusal = yes(args, 'set_pod_config with recreate'); if (refusal) return text(refusal, true) }
        let saved
        if (args.reset) saved = pods.setConfig(args.pod_id, null)
        else saved = pods.setConfig(args.pod_id, mergeConfig(pods.config(args.pod_id) || mounts.load(), args.patch || {}))
        const fresh = args.recreate ? await pods.recreate(args.pod_id) : null
        return json({ ...saved, config: saved.config ? summaryOf(saved.config) : null, recreated_as: fresh ? fresh.id : null })
      } },

    // ---------- the Default Configuration and the keys ----------
    { name: 'set_configuration', description: '[folder_excludes ({ project, plates, comfy-shared, workflows: [patterns] }, ADR-011: per-folder exclusion defaults, relative to THAT folder\'s root, added to sync_exclude for that step only; a pod\'s own map replaces the Default\'s per key, an empty list clears the key for the pod; at most 100 per key and 300 in all) and sync_exclude_delete (a push with exclusions also removes what the patterns match on the volume, a guarded removal that still needs a named yes; default false) are part of the configuration.] [sync_exclude (a list of folder or file patterns a push leaves out, rsync semantics: `/X/` the top-level folder, `X/` folders anywhere, `X` anything named X) is part of the configuration (ADR-011): the pod\'s own list replaces the Default\'s; a run\'s `exclude` is added; default []; they only remove things from a push.] [render { where, kind, proxy_width, review_width, codecs, fps, pull } is part of the configuration (ADR-048): how DPX sequences are rendered; default { auto, proxy, source, source, [prores422hq], auto, true }; no approver and no allow_partial are ever stored.] [auto_sync { enabled, pull, push, approved_by } is part of the configuration (ADR-046): Auto sync for each pod created under it; enabled: true needs approved_by, the named yes; default off, Pull on, Push off.] Change the Default Configuration: a patch (objects such as folders, env, required merge by key; lists and the rest replace). Same validation as the window. dry_run (no-spend) is never settable. Returns the saved summary.',
      inputSchema: obj({ patch: O('Fields to change, as get_configuration shows them: folders {key: path}, network_volume_id, data_center_id, mount_path, image, registry_auth_id, idle_stop_minutes, apply_by_default, env {NAME: value}, links, custom, required, sync_shared, pull_shared, pull_any_card, default_gpu (the card a new pod gets when none is named: a table key or auto), mcp_http ...') }, ['patch']),
      run: async ({ patch }) => { const saved = mounts.put(mergeConfig(mounts.load(), patch || {})); return json({ saved: true, configuration: summaryOf(mounts.load()), warnings: saved.warnings ?? undefined }) } },
    { name: 'preview_configuration', description: '[folder_excludes ({ project, plates, comfy-shared, workflows: [patterns] }, ADR-011: per-folder exclusion defaults, relative to THAT folder\'s root, added to sync_exclude for that step only; a pod\'s own map replaces the Default\'s per key, an empty list clears the key for the pod; at most 100 per key and 300 in all) and sync_exclude_delete (a push with exclusions also removes what the patterns match on the volume, a guarded removal that still needs a named yes; default false) are part of the configuration.] [sync_exclude (a list of folder or file patterns a push leaves out, rsync semantics: `/X/` the top-level folder, `X/` folders anywhere, `X` anything named X) is part of the configuration (ADR-011): the pod\'s own list replaces the Default\'s; a run\'s `exclude` is added; default []; they only remove things from a push.] [render { where, kind, proxy_width, review_width, codecs, fps, pull } is part of the configuration (ADR-048): how DPX sequences are rendered; default { auto, proxy, source, source, [prores422hq], auto, true }; no approver and no allow_partial are ever stored.] [auto_sync { enabled, pull, push, approved_by } is part of the configuration (ADR-046): Auto sync for each pod created under it; enabled: true needs approved_by, the named yes; default off, Pull on, Push off.] What a pod would get from a configuration without saving it: the env and the links. A patch over the Default Configuration, or none for the saved one', inputSchema: obj({ patch: O('Fields to change') }),
      run: async ({ patch }) => json(mounts.preview(mergeConfig(mounts.load(), patch || {}))) },
    { name: 'reset_configuration', description: 'Delete the saved Default Configuration and go back to the defaults (the keys and settings are separate and stay)', inputSchema: obj(),
      run: async () => json({ reset: true, configuration: summaryOf(mounts.reset()) }) },
    { name: 'get_local_env', description: "The shell lines (export NAME=...) that set this PC up like a pod: the mapped folders as variables, for a terminal or an IDE run configuration", inputSchema: obj(),
      run: async () => json(mounts.envLines(mounts.load())) },
    { name: 'list_dirs', description: "The folders on this PC under a path (the window's folder picker), for choosing what to map. The path stays the one you gave (Up goes back through a link); `real` is the realpath when it differs; a link to a folder has link: true and its target (a broken link is hidden); an unreadable folder is an error with a hint (macOS: Files and Folders / Full Disk Access). At most 2,000 folders come back, sorted, with `total` and `truncated` (how many were left out); filter narrows a huge folder first. A folder that does not answer within 15 s is a timeout error (a sleeping drive or an unavailable network mount). With volumes: true it lists the volumes mounted on this PC instead (macOS /Volumes, Linux /media, /run/media, /mnt): name, path, link, target, size_bytes, free_bytes, readable (a mount that does not answer within 3 s is listed unreadable)", inputSchema: obj({ path: S('Absolute path; omit for the home folder'), hidden: B('Include dot folders'), filter: S('Only folders whose name contains this (case-insensitive), applied before the cap'), volumes: B('List the mounted volumes instead of a folder') }),
      run: async ({ path, hidden, volumes, filter }) => { try { return volumes ? json(await core.listVolumes()) : json(await core.listDirs(path || '', !!hidden, String(filter || ''))) } catch (e) { return text(`${e.message}${e.hint ? ` (${e.hint})` : ''}`, true) } } },
    { name: 'get_settings', description: 'The API keys and settings: whether each key is set and its last four characters, never a value; the Panama bucket, region and profile', inputSchema: obj(),
      run: async () => json(settings.get()) },
    { name: 'set_settings', description: `Set or remove the pod manager's own keys and settings: ${SETTING_FIELDS.join(', ')}. A string sets it, null removes it (agent_named_yes_required is true or false: whether a spending tool asks for approved_by, off by default; agent_spend_cap_usd is a number of dollars advertised to agents, 0 or null for none; agent_shell_guard true installs a Bash hook into this OS user's Claude Code settings that refuses shell routes around the pod manager, false removes only that hook). Values are never returned (get_settings shows the last four characters). A key typed here is in this conversation's transcript: prefer entering it in the app if that matters. The no-spend switch is not a setting here.`,
      inputSchema: obj({ values: { type: 'object', description: 'field -> value or null', properties: Object.fromEntries(SETTING_FIELDS.map((f) => [f, { type: f === 'agent_named_yes_required' || f === 'agent_shell_guard' ? ['boolean', 'null'] : f === 'agent_spend_cap_usd' ? ['number', 'null'] : ['string', 'null'] }])), additionalProperties: false } }, ['values']),
      run: async ({ values }) => {
        const unknown = Object.keys(values || {}).filter((k) => !SETTING_FIELDS.includes(k))
        if (unknown.length) return text(`Not a setting: ${unknown.join(', ')}. Settings: ${SETTING_FIELDS.join(', ')}`, true)
        const after = settings.set(values)
        return json({ changed: Object.keys(values), settings: after })
      } },
    { name: 'check_anthropic_key', description: 'Whether the Anthropic key (the one saved, or one passed to try) is accepted; used by the adapter drafting and describing tools', inputSchema: obj({ key: S('A key to try without saving it') }),
      run: async ({ key }) => json(await settings.checkAnthropic(key || null)) },
    { name: 'config_export', description: 'The Default Configuration as the JSON the window exports (folders, volume, image, env, adapters list, ...). Keys and tokens are left out unless a file path is given: then the whole file, secrets included, is written there (mode 600) and not returned',
      inputSchema: obj({ file: S('Absolute path to write; with it, secrets are included'), include_secrets: B('With file: leave them out when false (default true)') }),
      run: async ({ file, include_secrets }) => {
        if (!file) return json({ file: null, suggested_name: configio.suggestedName(), config: configio.exportConfig({ includeSecrets: false }) })
        absolutePath(file, 'file')
        writeFileSync(file, JSON.stringify(configio.exportConfig({ includeSecrets: include_secrets !== false }), null, 2) + '\n', { mode: 0o600 })
        return json({ file, secrets_included: include_secrets !== false })
      } },
    { name: 'config_import_plan', description: 'What importing a configuration file would change, section by section (nothing is written): the folders (paths from another machine are flagged), the pod defaults, the keys (names and last four characters only)', inputSchema: obj({ file: S('Absolute path of the JSON file') }, ['file']),
      run: async ({ file }) => json(configio.planImport(readJsonFile(file))) },
    { name: 'config_import_apply', description: 'Import a configuration file: backs up first, then applies the sections named (default: the ones the plan ticks). dry_run defaults to true and only plans', inputSchema: obj({ file: S('Absolute path of the JSON file'), sections: { type: 'array', items: { type: 'string' }, description: 'Section keys from config_import_plan; omit for the ticked ones' }, dry_run: B('default true') }, ['file']),
      run: async ({ file, sections, dry_run = true }) => {
        const data = readJsonFile(file), plan = configio.planImport(data)
        if (dry_run !== false) return json({ dry_run: true, plan })
        const chosen = Array.isArray(sections) && sections.length ? sections : plan.sections.filter((s) => s.default_checked).map((s) => s.key)
        return json({ dry_run: false, sections: chosen, result: configio.applyImport(data, { sections: chosen }) })
      } },
    { name: 'config_undo', description: 'Undo the last configuration import from its backup', inputSchema: obj(), run: async () => json(configio.undoImport()) },
    { name: 'config_backups', description: 'The backups of the configuration that imports made', inputSchema: obj(), run: async () => json(configio.listBackups()) },

    // ---------- volumes ----------
    { name: 'resize_volume', description: `Grow a network volume (RunPod only grows them; billed monthly, USD 0.07 per GB). Spends money. approved_by is needed only when the named-yes setting is on. Create one in a chosen datacenter with create_volume`,
      inputSchema: obj({ approved_by: approved.properties.approved_by, volume_id: S('Volume ID (list_volumes)'), size_gb: N('The new size in GB, larger than now') }, ['volume_id', 'size_gb']),
      run: async (args) => {
        const refusal = yes(args, 'resize_volume'); if (refusal) return text(refusal, true)
        const v = await volumes.resize(args.volume_id, Number(args.size_gb))
        console.error(`resize_volume ${v.id} to ${v.size_gb} GB approved by ${String(args.approved_by).trim()}`)
        return json({ ...v, approved_by: String(args.approved_by).trim() })
      } },

    { name: 'volume_files', description: 'Explore a network volume: its folders to depth 3 with sizes (read-only). In a datacenter with the RunPod S3 API and with S3 keys set it goes through the S3 API from this PC (no pod, no cost); otherwise a short-lived pod of the cheapest card or your own pod on it does it (a few cents). Starts a job: poll it with volume_job. volume_plan says where it would run and what it costs. Spends a little: approved_by (only when the named-yes setting is on)',
      inputSchema: obj({ approved_by: approved.properties.approved_by, volume_id: S('Volume ID (list_volumes)'), path: S('A folder to list inside (default /workspace, the whole volume); folders deeper than three levels are listed by asking for them') }, ['volume_id']),
      run: async (args) => { const refusal = yes(args, 'volume_files'); if (refusal) return text(refusal, true); try { return json(await volumes_job.browse(args.volume_id, args.path)) } catch (e) { return text(e.message, true) } } },
    { name: 'volume_erase', description: `Empty chosen folders of a network volume (the volume and the folders stay; contents are deleted, not reversible). what: any of ${Object.keys(podpull.ERASABLE).join(', ')} (models is not in any default). Ask the user first: approved_by only when the named-yes setting is on, and confirm_name (the volume's exact name, typed back). Runs on a short-lived pod or your pod on it; refused while another job runs on the volume. Poll with volume_job; a volume_files listing first shows sizes`,
      inputSchema: obj({ approved_by: approved.properties.approved_by, volume_id: S('Volume ID (list_volumes)'), what: { type: 'array', items: { type: 'string' }, description: 'Folders to empty, from the list above' }, confirm_name: S("The volume's exact name") }, ['volume_id', 'what', 'confirm_name']),
      run: async (args) => { const refusal = yes(args, 'volume_erase'); if (refusal) return text(refusal, true); try { console.error(`volume_erase ${args.volume_id} [${(args.what || []).join(',')}] approved by ${String(args.approved_by).trim()}`); return json(await volumes_job.erase(args.volume_id, args.what || [], { approved_by: args.approved_by, confirm_name: args.confirm_name })) } catch (e) { return text(e.message, true) } } },
    { name: 'volume_clone', description: "Copy a network volume's files to another volume in another datacenter: to an existing volume (to_volume_id) or a new one (new_volume: name, size_gb, datacenter). RunPod to RunPod by default, no S3 needed: a short pod on each volume, and the target pod rsyncs from the source pod over SSH with a one-off key (removed afterwards); both pods are deleted at the end. With RunPod S3 keys in Default Configuration and an S3 datacenter on one side, one pod does it through the S3 API instead. The source is never changed; input/ is left out unless include_input. Spends (a new volume bills monthly, the pods hourly): approved_by (only when the named-yes setting is on). Poll with volume_job",
      inputSchema: obj({ approved_by: approved.properties.approved_by, volume_id: S('The source volume ID (list_volumes)'), to_volume_id: S('An existing volume to copy into'), new_volume: { type: 'object', properties: { name: S('Name'), size_gb: N('Size in GB'), datacenter: S('Datacenter id (list_datacenters)') }, description: 'Or make a new volume to copy into' }, include_input: { type: 'boolean', description: 'Also copy input/ (default no)' } }, ['volume_id']),
      run: async (args) => { const refusal = yes(args, 'volume_clone'); if (refusal) return text(refusal, true); try { console.error(`volume_clone ${args.volume_id} approved by ${String(args.approved_by).trim()}`); return json(await podpull.cloneVolume(args.volume_id, { approved_by: args.approved_by, to_volume_id: args.to_volume_id, new_volume: args.new_volume, include_input: !!args.include_input })) } catch (e) { return text(e.message, true) } } },
    { name: 'volume_job', description: 'A volume_files, volume_erase, volume_clone or models_fetch job: its state, the pod, the listing (folders and bytes) or what an erase freed from each folder. action cancel stops it (the pod is deleted)', inputSchema: obj({ job_id: S('The job id the call returned'), action: S('status (default) | cancel'), plan_volume_id: S('Instead of a job: a volume ID whose job plan (where it would run, the card and price) to show') }, []),
      run: async (a) => { try { if (a.plan_volume_id) return json(await podpull.volumePlan(a.plan_volume_id)); if (!a.job_id) return text('Give job_id (or plan_volume_id)', true); const j = a.action === 'cancel' ? podpull.cancel(a.job_id) : podpull.job(a.job_id); return j ? json(j) : text(`No such job: ${a.job_id}`, true) } catch (e) { return text(e.message, true) } } },

    { name: 'volume_jobs', description: 'The jobs that work on a volume (a models_fetch / models_load_wanted download with its progress: file i of n, bytes done of total, rate, ETA; volume_files, erase, clone, models_delete), newest first, and the temporary pods of volume jobs this app lost when it was restarted (`interrupted`: they keep billing; delete one with action drop and its name, or delete_pod with its pod_id; a download is detached on its pod, so one the app lost, or could not reach for ten minutes, may still be downloading: action reattach and its name follows it again, rebuilding the progress from the pod\'s log). Read-only unless action is drop or reattach', inputSchema: obj({ action: S('list (default) | drop | reattach'), name: S('drop, reattach: the interrupted pod name from the list (ComfyUI-Pull-vol-...)') }),
      run: async (a) => { try { if (a.action === 'reattach') { if (!a.name) return text('Give name (the interrupted pod from the list)', true); return json(await podpull.reattach(a.name)) } if (a.action === 'drop') { if (!a.name) return text('Give name (the interrupted pod from the list)', true); return json(await podpull.dropInterrupted(a.name)) } return json(podpull.volumeJobs()) } catch (e) { return text(e.message, true) } } },

    { name: 'rate_limit_status', description: "Whether RunPod is limiting this app's requests (its API allows so many a minute and an hour): limited, the window (minute or hour), when the app tries again (retry_at), and how old the answer is that the lists are showing from the cache (stale_age_s). Local state: it makes no request to RunPod. While limited, list_pods, list_volumes, get_volume_info and the stock tools answer from the last good answer; object answers carry `rate_limited`", inputSchema: { type: 'object', properties: {} },
      run: async () => json(core.ratelimit.status()) },
    { name: 'agent_guard_status', description: 'The agent shell guard: enabled (the setting), installed (the hook entry is in this OS user Claude Code settings and its script exists and is executable), the settings file and the script path. Read-only; switch it with set_settings agent_shell_guard', inputSchema: obj(),
      run: async () => { try { return json(core.agentguard.status()) } catch (e) { return text(e.message, true) } } },
    // ---------- Models (ADR-042): Hugging Face onto the Shared volume ----------
    { name: 'models_search', description: 'Search Hugging Face for model repos (public API, no key): id, downloads, likes, last update, whether gated. Read-only', inputSchema: obj({ query: S('What to search for, at least two characters') }, ['query']),
      run: async ({ query }) => { try { return json(await hf.search(query)) } catch (e) { return text(e.message, true) } } },
    { name: 'models_files', description: `A Hugging Face repo's weight files (${hf.EXTENSIONS.join(', ')}) with exact size, sha256 and the models folder each probably belongs in (${hf.FOLDERS.join(', ')}). Read-only`, inputSchema: obj({ repo: S('owner/name'), revision: S('Branch or tag, default main') }, ['repo']),
      run: async ({ repo, revision }) => { try { return json(await hf.files(repo, revision || 'main')) } catch (e) { return text(e.message, true) } } },
    { name: 'models_fetch', description: 'Load weight files from Hugging Face onto the Shared volume (set_shared_volume; else the Default Configuration volume) into comfy-shared/models/<folder>/: a short pod, or your own pod on that volume, downloads them (resumable, sha256 checked, a file already there at the right size is skipped) and the pod is deleted at the end. Repo and path are looked up on Hugging Face again, only safetensors, gguf and pth files, at most 20 at a time. Spends the pod minutes (cents); no approval needed. Starts a job: poll it with volume_job', inputSchema: obj({ volume_id: S('A volume ID (default: the Shared volume)'), items: { type: 'array', items: { type: 'object', properties: { repo: S('owner/name'), path: S('File path in the repo, from models_files'), revision: S('Branch or tag, default main'), folder: S(`Destination under models/: ${hf.FOLDERS.join(', ')}`) }, required: ['repo', 'path', 'folder'] }, description: 'The files to load' } }, ['items']),
      run: async ({ volume_id, items }) => { try { const cfg = mounts.load(); const vol = volume_id || cfg.shared_volume_id || cfg.network_volume_id; if (!vol) return text('No volume: pass volume_id, or choose the Shared volume or a default volume', true); console.error(`models_fetch ${vol} ${(items || []).length} file(s)`); return json(await podpull.fetchModels(vol, items || [], {})) } catch (e) { return text(e.message, true) } } },
    { name: 'models_status', description: 'What the Shared volume (or the volume given) holds under comfy-shared/models/, as a list of folder, name and bytes. Over the RunPod S3 API from this PC (no pod, no cost); null when the volume has no S3 API or no S3 keys are set. Read-only', inputSchema: obj({ volume_id: S('A volume ID (default: the Shared volume)') }, []),
      run: async ({ volume_id }) => { try { const cfg = mounts.load(); const vol = volume_id || cfg.shared_volume_id || cfg.network_volume_id; if (!vol) return text('No volume: pass volume_id, or choose the Shared volume or a default volume', true); return json({ volume_id: vol, shared: vol === cfg.shared_volume_id, models: await podpull.modelsOnVolume(vol) }) } catch (e) { return text(e.message, true) } } },
    { name: 'models_delete', description: "Delete model files from the Shared volume (or volume_id): each item is {folder, name} as models_status lists them (folder directly under comfy-shared/models/, name under it, sub-folders allowed). Exact files only: no folder, no pattern, never the _canalv2_pull bookkeeping folder. Not reversible, so confirmed must be true (the window asks first). Over the RunPod S3 API when the volume has it (no pod, no cost), else a short pod. Refused while another job runs on the volume. A deleted file stays in the wanted-models list and shows as missing. Follow the job with volume_job. approved_by only when the named-yes setting is on", inputSchema: obj({ volume_id: S('A volume ID (default: the Shared volume)'), items: { type: 'array', items: obj({ folder: S('Folder under models/, e.g. vae'), name: S('File name under it, e.g. seedvr2_ema_vae_fp16.safetensors') }, ['folder', 'name']), description: 'Files to delete, at most 200' }, confirmed: B('Must be true: this cannot be undone'), approved_by: approved.properties.approved_by }, ['items', 'confirmed']),
      run: async (args) => { const refusal = yes(args, 'models_delete'); if (refusal) return text(refusal, true); try { const cfg = mounts.load(); const vol = args.volume_id || cfg.shared_volume_id || cfg.network_volume_id; if (!vol) return text('No volume: pass volume_id, or choose the Shared volume or a default volume', true); console.error(`models_delete ${vol} ${(args.items || []).length} file(s)`); return json(await podpull.deleteModels(vol, args.items || [], { confirmed: args.confirmed === true }, {})) } catch (e) { return text(e.message, true) } } },
    { name: 'models_wanted', description: "The wanted-models list (ADR-042 section 12): the model files wanted on a Shared volume, as Hugging Face coordinates (repo, path), the models folder and the size. It travels in config_export / config_import_apply (section wanted_models) and is tied to no volume. With volume_id (or a Shared / default volume with the S3 API) each row says whether it is on that volume (present, missing, unknown) and the totals say how much is missing and whether the volume is too small. Read-only, no cost", inputSchema: obj({ volume_id: S('A volume ID; omitted: the Shared volume, else the default one; pass none to get the plain list'), plain: B('true: only the list, no comparison with a volume') }, []),
      run: async ({ volume_id, plain }) => { try { if (plain) return json({ models: wantedmodels.list() }); try { return json(await wantedmodels.status(volume_id || '')) } catch (e) { return json({ models: wantedmodels.list(), note: `Not compared with a volume: ${e.message}` }) } } catch (e) { return text(e.message, true) } } },
    { name: 'models_wanted_add', description: "Add to the wanted-models list: items (each {folder, repo, path, bytes, sha256?, revision?, note?}; folder is one of the models folders with at most one sub-folder), or csv (Binc's pull list text: pipeline,install_to,file,hf_repo,hf_path,bytes,notes), or from: 'binc_list' (the window's Install Defaults: reads comfy-shared/models/_canalv2_pull/MODELS_PULL_v003.csv off the volume over S3) or 'installed' (the window's Saved List: records the weight files the volume holds; the repo of one already in the list is kept, else it has none). Merged by repo, path and folder. Our side only, no spend", inputSchema: obj({ items: { type: 'array', items: { type: 'object' }, description: 'Entries to add' }, csv: S("Binc's pull list as CSV text"), from: S('binc_list or installed', { enum: ['binc_list', 'installed'] }), volume_id: S('The volume to read for from (default: the Shared volume)') }, []),
      run: async ({ items, csv, from, volume_id }) => { try { if (csv) return json(await wantedmodels.addPullList({ csv })); if (from === 'binc_list') return json(await wantedmodels.addPullList({ volume_id })); if (from === 'installed') return json(await wantedmodels.saveInstalled(volume_id || '')); return json(wantedmodels.add(items || [])) } catch (e) { return text(e.message, true) } } },
    { name: 'models_wanted_remove', description: 'Remove entries from the wanted-models list by key (the key in models_wanted rows: repo|path|folder), or all of them. Our side only, no spend', inputSchema: obj({ keys: { type: 'array', items: { type: 'string' }, description: 'Row keys' }, all: B('Remove every entry') }, []),
      run: async ({ keys, all }) => { try { return json(wantedmodels.remove(keys || [], !!all)) } catch (e) { return text(e.message, true) } } },
    { name: 'models_load_wanted', description: 'Load the wanted models the volume lacks onto it (the Shared volume, else the default one, or volume_id; any datacenter): the same Hugging Face fetch as models_fetch, in jobs of at most 20 files one after another (the first is returned; follow it with volume_job; the rest start as each finishes). Entries with no repo cannot be loaded; gated repos are refused. Spends short-pod minutes and writes the volume; the answer says how many GB and warns when the volume is too small (resize_volume first)', inputSchema: obj({ ...approved.properties, volume_id: S('A volume ID (default: the Shared volume)') }, []),
      run: async (args) => { const refusal = yes(args, 'models_load_wanted'); if (refusal) return text(refusal, true); try { console.error(`models_load_wanted ${args.volume_id || '(shared)'}`); return json(await wantedmodels.loadMissing(args.volume_id || '', { approved_by: args.approved_by })) } catch (e) { return text(e.message, true) } } },
    { name: 'set_shared_volume', description: 'Choose the volume that holds the shared models: it is marked Shared in the Volumes list and cannot be deleted (delete_volume refuses it). An empty volume_id clears it. Our side only, no spend', inputSchema: obj({ volume_id: S('A volume ID (list_volumes); empty clears') }, []),
      run: async ({ volume_id }) => { try { return json(await volumes.setShared(volume_id || '')) } catch (e) { return text(e.message, true) } } },

    // ---------- Panama / BH ----------
    { name: 'panama_status', description: 'Is the BH exchange bucket reachable: the bucket, region, how it is read (the keys in the app or an AWS profile), where rounds are staged on this PC, and whether Pod mode is available', inputSchema: obj(), run: async () => json(panama.status()) },
    { name: 'list_rounds', description: "The rounds a source offers, in the one shape Import Round lists (id, name, shots, staged, verified, importable, and for the BH bucket how much is on this PC: state none/partial/unverified/complete with files present and expected). source: which one (default panama-s3, the BH bucket; `volume` = Binc's rounds already under comfy-shared/workflows/ on a network volume, listed read-only over RunPod's S3 API from this PC: no pod, no cost; items carry graphs, locked shots (reference only) and variants); volume_id: which volume for source volume (default the Shared volume, else the default one); sources: true lists the sources and whether each can be used now and why not (status: true does that for one source and volume). Read-only", inputSchema: obj({ source: S('Source id, default panama-s3; or volume'), volume_id: S('source volume: the network volume to read (list_volumes); default the Shared volume'), sources: B('List the sources instead of a source\'s rounds'), status: B('Can this source (and volume) be used now, and why not; spends nothing') }), run: async ({ source, volume_id, sources, status }) => { try { return json(sources ? library.sources() : status ? await library.status(source || undefined, { volume_id: volume_id || undefined }) : await library.list(source || undefined, { volume_id: volume_id || undefined })) } catch (e) { return text(e.message, true) } } },
    { name: 'round_info', description: "What one round on a volume is, from the round adapter (brynley-rounds-layout) reading a prefix listing of comfy-shared/workflows/<round>/ over S3 (read-only, no pod, no cost): { kind, round, shots[], variants[], graphs[] (path as the pod's Workflows panel names it, shot, variant, bytes, locked), locked[], findings[] }. Locked shots (cgi-042, anything under 04_GRAPH) are listed for reference and are never run. models: true also checks the round's graphs' model names against the volume's model list (reads each graph's JSON, at most max_graphs, default 60) and says per graph which models are missing and where the same file name sits in another models folder; changes and fetches nothing. Read-only", inputSchema: obj({ round: S('The round folder, e.g. proxy_v005'), volume_id: S('The network volume (default the Shared volume)'), files: B('Instead return the round\'s files as a tree (folders with totals, files with sizes; one prefix listing, at most 3000 files, `truncated` says if more); `shot` narrows it to one shot'), shot: S('files: only this shot\'s folder'), models: B('Also check the models (the preflight)'), shots: { type: 'array', items: { type: 'string' }, description: 'models: only these shots' }, max_graphs: N('models: at most this many graphs (default 60)') }, ['round']), run: async ({ round, volume_id, files, shot, models, shots, max_graphs }) => { try { return json(files ? await library.roundFiles(volume_id || undefined, round, shot || '') : models ? await library.preflight(volume_id || undefined, round, { shots, max_graphs }) : await library.round(volume_id || undefined, round)) } catch (e) { return text(e.message, true) } } },
    { name: 'panama_rounds', description: 'The delivery rounds in the bucket with what is staged: on this PC (target local) or on the network volume as last seen by a pod (target pod). Per round: state (none, partial, unverified, complete), files present and expected, bytes', inputSchema: obj({ target }),
      run: async (args) => json(args.target === 'pod' ? await podpull.rounds() : panama.rounds()) },
    { name: 'panama_round_files', description: "One round's files in the bucket as a folder tree (read-only), each marked when already on this PC. Folders carry totals. Narrow with prefix; the list is cut at limit", inputSchema: obj({ round: S('Round name'), prefix: S('Only paths under this folder'), limit: N('At most this many entries (default 300)') }, ['round']),
      run: async ({ round, prefix, limit }) => {
        const r = panama.files(round), p = String(prefix || '').replace(/^\/+|\/+$/g, '')
        const all = p ? r.entries.filter((e) => e.path === p || e.path.startsWith(`${p}/`)) : r.entries
        const n = Math.max(1, Math.min(Number(limit) || 300, 5000))
        return json({ round, files: r.files, bytes: r.bytes, shown: Math.min(all.length, n), matching: all.length, entries: all.slice(0, n) })
      } },
    { name: 'panama_bucket_list', description: "One level of the BH exchange bucket (read-only, what Network Volumes > Explore shows): the folders and files directly under prefix ('' is the top; e.g. rounds/ or returns/BKK/), each file with bytes and modified. Cut at 2000 entries (truncated: true). Only lists; never writes", inputSchema: obj({ prefix: S("Folder in the bucket, no leading slash, no '..'; default the top") }),
      run: async ({ prefix }) => { try { return json(await panama.browse(prefix || '')) } catch (e) { return text(e.message, true) } } },
    { name: 'panama_stage',description: "Stage a round from this PC (what a drop on the Import Round(s) window does): a folder or files are copied, a .zip is extracted, into a new folder under the staging folder, then it is a staged round like a downloaded one. Nothing is overwritten and nothing leaves this PC; no spend", inputSchema: obj({ paths: { type: 'array', items: { type: 'string' }, description: 'Absolute paths of folders, .zip files or files' } }, ['paths']), run: async ({ paths }) => json(panama.stageDrop(paths)) },
    { name: 'panama_round_size', description: 'Files and bytes in one round (a listing; a big round takes a few seconds)', inputSchema: obj({ round: S('Round name') }, ['round']), run: async ({ round }) => json(panama.size(round)) },
    { name: 'panama_pod_plan', description: 'What a pod download of a round would do before it does it: use a pod of yours or start a short-lived one, its card and price, the volume, the size, the ceiling in minutes', inputSchema: obj({ round: S('Round name'), route: S("'current' (your pod on the volume, started first if it is off) or 'temporary' (a sync-agent pod of the cheapest card). Default: your pod if it runs, else temporary") }, ['round']), run: async ({ round, route }) => json(await podpull.plan(round, route ? { route } : {})) },
    { name: 'panama_pull', description: 'Download a round: to this PC (aws s3 sync, resumable, never deletes) or onto the network volume by a pod. Returns a job; follow it with panama_job. A pod download may start a pod: approved_by (only when the named-yes setting is on)',
      inputSchema: obj({ round: S('Round name'), target, route: S("Pod downloads: 'current' (your pod, started first if off) or 'temporary' (sync-agent pod, cheapest card)"), approved_by: approved.properties.approved_by, shots: { type: 'array', items: { type: 'string' }, description: 'Pod downloads: only these shots (and the round\'s shared files); the other shot folders stay in the bucket. Omitted: the whole round' } }, ['round']),
      run: async (args) => {
        if (args.target === 'pod') { const refusal = yes(args, 'panama_pull on a pod'); if (refusal) return text(refusal, true); console.error(`panama_pull ${args.round} on a pod approved by ${String(args.approved_by).trim()}`) }
        return json(args.target === 'pod' ? await podpull.pull(args.round, { ...(args.route ? { route: args.route } : {}), ...(args.shots?.length ? { shots: args.shots } : {}) }) : panama.pull(args.round))
      } },
    { name: 'panama_job', description: 'Where a download (or delete) is: state, files, bytes done of total, rate, the latest files', inputSchema: obj({ id: S('Job id from panama_pull'), target }, ['id']),
      run: async (args) => { const j = pickPanama(args).job(args.id); return j ? json(j) : text(`No such job: ${args.id}`, true) } },
    { name: 'panama_cancel', description: 'Stop a download; what is already there stays and a later pull resumes', inputSchema: obj({ id: S('Job id'), target }, ['id']), run: async (args) => json(pickPanama(args).cancel(args.id)) },
    { name: 'panama_remove', description: "Delete a round's staged copy: on this PC, or on the volume by a pod (approved_by (only when the named-yes setting is on): it uses a pod). The bucket is read-only and never touched", inputSchema: obj({ round: S('Round name'), target, approved_by: approved.properties.approved_by }, ['round']),
      run: async (args) => {
        if (args.target === 'pod') { const refusal = yes(args, 'panama_remove on a pod'); if (refusal) return text(refusal, true); return json(await podpull.remove(args.round)) }
        return json(panama.remove(args.round))
      } },
    { name: 'plan_round_import', description: "What importing a round would do and cost before it does anything (ADR-038): its shots, the pod price, the estimate, the pod limit and the dollar cap (the Default Configuration's import_max_pods / import_cost_cap_usd, unless import_cap_enabled is off)", inputSchema: obj({ round: S('Round name'), source: S('panama-s3 (BH, default) or volume: a round already on a network volume (ADR-044), run in place: no pull, nothing copied, nothing on the volume written or replaced (replace/overwrite are refused). The plan then has graphs, seconds_per_graph, the estimate with its assumption, locked/refused shots and the cap left; locked shots (cgi-042, 04_GRAPH) are never run'), volume_id: S('source volume: the volume the round sits on (default the Shared volume)'), shots: { type: 'array', items: { type: 'string' }, description: 'Only these shots (default: all; for a volume round all that are not locked)' }, run_workflows: B('Also run each shot\'s workflows (default true)'), cards: { type: 'object', description: 'shot -> a GPU card key (see list_gpus) or a LIST of card keys of ONE datacenter in your order of preference; a shot with a card gets a pod of its own: every new pod asks the cards in that order starting from the first and the first with a card free is used (all pods get the first card while it has free GPUs; only a definite no-card goes on to the next; one pod per attempt). One without takes the pool. The estimate is priced at the most expensive listed card', additionalProperties: { anyOf: [{ type: 'string' }, { type: 'array', items: { type: 'string' } }] } }, max_pods: { type: 'number', description: 'Number of pods (at once): the job is split into this many chunks, one pod per chunk; at most this many shots run at the same time, the rest wait for a pod to free up' }, cost_cap_usd: { type: 'number', description: 'Dollar cap on the estimate' }, generate_outputs: { type: 'boolean', description: "Generate Outputs (needs run_workflows and approved_by): when each pod's workflows finish, render the review videos of the NEW complete DPX sequences of its shot on that pod, with the Default Configuration's render settings (kind, codecs, colour), no new pod, nothing pulled, skip existing. Acts under approved_by; the plan shows it" }, publish: { anyOf: [{ type: 'boolean' }, { type: 'object', properties: { s3: { type: 'boolean' }, slack: { type: 'boolean' } } }], description: "Publish (needs generate_outputs, run_workflows and approved_by, a person's name, never guessed): when the render finishes, publish the finished videos from the volume to S3 under approved_by, into the Auto-publish round (and the DPX frames when auto_publish.include_dpx is on). true = S3, plus Slack only when the Default Configuration's render.publish.slack is on; { s3: true, slack: true } chooses; Slack only with S3. Publish settings must be ready (400 with the reason otherwise). A locked shot and model weights are never published. This sends files out of the app: it is recorded in History with the name" }, auto_sync: { anyOf: [{ type: 'boolean' }, { type: 'object', properties: { pull: { type: 'boolean' }, push: { type: 'boolean' } } }], description: 'Auto sync (docs/ADR-046) for the pods this CREATES (pods reused from the pool are not changed): true = pull the volume\'s changes to this PC, or { pull, push }. Turned on with approved_by as the named yes. See auto_sync' } }, ['round']), run: async ({ round, ...o }) => json(await queue.planImport(round, o)) },
    { name: 'import_rounds', description: "Import SEVERAL rounds on one approval (what the Import Round(s) window does): each is its own import in the queue; cost_cap_usd is the TOTAL and is split evenly between them. Every round is planned first, so a bad round or card queues nothing. Per round: shots (default all) and cards ({ shot: card key, or a list of card keys in your order }); max_pods is per round. Spends money: approved_by (only when the named-yes setting is on). Follow with queue_list", inputSchema: obj({ rounds: { type: 'array', description: 'The rounds', items: { type: 'object', properties: { round: S('Round name'), shots: { type: 'array', items: { type: 'string' } }, cards: { type: 'object', description: 'shot -> a card key or an ordered list of card keys (the first free one is used; most expensive priced)', additionalProperties: { anyOf: [{ type: 'string' }, { type: 'array', items: { type: 'string' } }] } }, max_pods: { type: 'number', description: 'Number of pods (at once) for this round; the shots are split among them' }, auto_sync: { anyOf: [{ type: 'boolean' }, { type: 'object' }], description: 'Auto sync for the pods this round creates (overrides the import-wide choice)' }, generate_outputs: { type: 'boolean', description: 'Generate Outputs for this round (overrides the import-wide choice)' }, publish: { anyOf: [{ type: 'boolean' }, { type: 'object' }], description: 'Publish for this round (overrides the import-wide choice; needs generate_outputs)' } }, required: ['round'] } }, source: S('panama-s3 (BH, default) or volume: the rounds already sit on volume_id and are run in place (ADR-044): no pull; locked shots are refused, an estimate over the cap is refused'), run_workflows: B('Also run each shot\'s workflows (default true)'), volume_id: S('The network volume the pods and pulls use (list_volumes); it becomes the default volume. Default: the current default, which must exist; source volume: where the rounds sit'), cost_cap_usd: { type: 'number', description: 'Dollar cap, total for all rounds' }, generate_outputs: { type: 'boolean', description: "Generate Outputs (needs run_workflows and approved_by): when each pod's workflows finish, render the review videos of the NEW complete DPX sequences of its shot on that pod, with the Default Configuration's render settings (kind, codecs, colour), no new pod, nothing pulled, skip existing. Acts under approved_by; the plan shows it" }, publish: { anyOf: [{ type: 'boolean' }, { type: 'object', properties: { s3: { type: 'boolean' }, slack: { type: 'boolean' } } }], description: "Publish (needs generate_outputs, run_workflows and approved_by, a person's name, never guessed): when the render finishes, publish the finished videos from the volume to S3 under approved_by, into the Auto-publish round (and the DPX frames when auto_publish.include_dpx is on). true = S3, plus Slack only when the Default Configuration's render.publish.slack is on; { s3: true, slack: true } chooses; Slack only with S3. Publish settings must be ready (400 with the reason otherwise). A locked shot and model weights are never published. This sends files out of the app: it is recorded in History with the name" }, auto_sync: { anyOf: [{ type: 'boolean' }, { type: 'object', properties: { pull: { type: 'boolean' }, push: { type: 'boolean' } } }], description: 'Auto sync (docs/ADR-046) for the pods this CREATES (pods reused from the pool are not changed): true = pull the volume\'s changes to this PC, or { pull, push }. Turned on with approved_by as the named yes. See auto_sync' }, approved_by: approved.properties.approved_by }, ['rounds']),
      run: async (args) => { const refusal = yes(args, 'import_rounds'); if (refusal) return text(refusal, true); const outs = needsName(args, args.rounds); if (outs) return text(outs, true); console.error(`import_rounds ${(args.rounds || []).map((r) => r.round).join(',')} approved by ${String(args.approved_by).trim()}`); const { approved_by, rounds, ...o } = args; return json(await queue.importRounds(rounds || [], { ...o, approved_by: String(approved_by).trim() })) } },
    { name: 'import_round', description: "Import a round (ADR-038): queue one pull (which also places the round) and one run-workflows task per shot; pods of the pool take them, restarted or created within the pod limit and the dollar cap. One approval covers the whole import. Spends money: approved_by (only when the named-yes setting is on). Follow it with queue_list", inputSchema: obj({ round: S('Round name'), source: S('panama-s3 (BH, default) or volume: the round already sits on volume_id and is run in place (ADR-044): NO pull, one run task per shot; a locked shot (cgi-042, 04_GRAPH) is refused, an estimate over the cap is refused, replace/overwrite are refused'), shots: { type: 'array', items: { type: 'string' }, description: 'Only these shots (default: all; a volume round: all that are not locked)' }, run_workflows: B('Also run each shot\'s workflows (default true; a volume round needs it)'), volume_id: S('The network volume the pods and pulls use (list_volumes); it becomes the default volume; source volume: where the round sits'), cards: { type: 'object', description: 'shot -> a GPU card key (see list_gpus) or a LIST of card keys of ONE datacenter in your order of preference; a shot with a card gets a pod of its own: every new pod asks the cards in that order starting from the first and the first with a card free is used (all pods get the first card while it has free GPUs; only a definite no-card goes on to the next; one pod per attempt). One without takes the pool. The estimate is priced at the most expensive listed card', additionalProperties: { anyOf: [{ type: 'string' }, { type: 'array', items: { type: 'string' } }] } }, max_pods: { type: 'number', description: 'Number of pods (at once): the job is split into this many chunks, one pod per chunk; at most this many shots run at the same time, the rest wait for a pod to free up' }, cost_cap_usd: { type: 'number', description: 'Dollar cap on the estimate' }, generate_outputs: { type: 'boolean', description: "Generate Outputs (needs run_workflows and approved_by): when each pod's workflows finish, render the review videos of the NEW complete DPX sequences of its shot on that pod, with the Default Configuration's render settings (kind, codecs, colour), no new pod, nothing pulled, skip existing. Acts under approved_by; the plan shows it" }, publish: { anyOf: [{ type: 'boolean' }, { type: 'object', properties: { s3: { type: 'boolean' }, slack: { type: 'boolean' } } }], description: "Publish (needs generate_outputs, run_workflows and approved_by, a person's name, never guessed): when the render finishes, publish the finished videos from the volume to S3 under approved_by, into the Auto-publish round (and the DPX frames when auto_publish.include_dpx is on). true = S3, plus Slack only when the Default Configuration's render.publish.slack is on; { s3: true, slack: true } chooses; Slack only with S3. Publish settings must be ready (400 with the reason otherwise). A locked shot and model weights are never published. This sends files out of the app: it is recorded in History with the name" }, auto_sync: { anyOf: [{ type: 'boolean' }, { type: 'object', properties: { pull: { type: 'boolean' }, push: { type: 'boolean' } } }], description: 'Auto sync (docs/ADR-046) for the pods this CREATES (pods reused from the pool are not changed): true = pull the volume\'s changes to this PC, or { pull, push }. Turned on with approved_by as the named yes. See auto_sync' }, approved_by: approved.properties.approved_by }, ['round']),
      run: async (args) => { const refusal = yes(args, 'import_round'); if (refusal) return text(refusal, true); const outs = needsName(args, [args]); if (outs) return text(outs, true); console.error(`import_round ${args.round} approved by ${String(args.approved_by).trim()}`); const { approved_by, round, ...o } = args; return json(await queue.importRound(round, { ...o, approved_by: String(approved_by).trim() })) } },
    { name: 'queue_list', description: "A failed or held task carries `failure` (stage, node, message, missing models, recovery, retryable, text). The queue (ADR-038): every import with its limits, spent estimate and task counts, and every task (pull or run per shot) with its state (waiting, running, done, failed, held, cancelled, interrupted), pod and error", inputSchema: obj({}), run: async () => json(queue.list()) },
    { name: 'queue_task', description: "Act on the queue: cancel or retry a task, cancel a whole import, purge finished imports from the queue (purge: ask the user first, then confirmed: true; id optional = one import; older_than_days optional), or change an import's limits (set_limits, then retry its held tasks). Retrying a task that spends is covered by the import's original approval", inputSchema: obj({ action: S('cancel | retry | cancel_import | set_limits | purge'), id: S('Task id (cancel, retry) or import id (cancel_import, set_limits, purge) from queue_list'), confirmed: { type: 'boolean', description: 'purge: true only after the user said yes' }, older_than_days: { type: 'number', description: 'purge: only imports finished this many days ago or more' }, max_pods: { type: ['number', 'null'], description: 'set_limits: pods at once (null = no limit)' }, cost_cap_usd: { type: ['number', 'null'], description: 'set_limits: dollar cap (null = no cap)' } }, ['action', 'id']),
      run: async ({ action, id, max_pods, cost_cap_usd, confirmed, older_than_days }) => { try { if (action === 'purge') return json(queue.purge({ confirmed, ...(id ? { import_id: id } : {}), ...(older_than_days !== undefined ? { older_than_days } : {}) })); if (action === 'cancel') return json(queue.cancelTask(id)); if (action === 'retry') return json(queue.retryTask(id)); if (action === 'cancel_import') return json(queue.cancelImport(id)); if (action === 'set_limits') return json(queue.setImportLimits(id, { ...(max_pods !== undefined ? { max_pods } : {}), ...(cost_cap_usd !== undefined ? { cost_cap_usd } : {}) })); return text(`Unknown action ${action}`, true) } catch (e) { return text(e.message, true) } } },
    { name: 'list_pod_workflows', description: "The graphs in a running pod's Workflows panel (its comfy-shared/workflows), grouped by folder (a shot or a round). What the Run workflows window lists (ADR-037)", inputSchema: obj({ pod_id: S('A running pod') }, ['pod_id']), run: async ({ pod_id }) => json(await runflows.list(pod_id)) },
    { name: 'run_pod_workflows', description: "Run chosen graphs from a pod's Workflows panel on that pod, one after another (ADR-037). Each UI graph is converted with ComfyUI's own frontend (on the pod if its image has it, else Chrome on this PC), queued and waited for; locked shots are refused. Every outcome and error is written to the History. Returns a job: follow it with run_workflows_job. Runs on a pod that is already billing: approved_by (only when the named-yes setting is on)", inputSchema: obj({ pod_id: S('A running pod'), paths: { type: 'array', items: { type: 'string' }, description: 'Panel paths from list_pod_workflows, e.g. rounds/<round>/<shot>/graph.json' }, approved_by: approved.properties.approved_by }, ['pod_id', 'paths']),
      run: async (args) => { const refusal = yes(args, 'run_pod_workflows'); if (refusal) return text(refusal, true); console.error(`run_pod_workflows on ${args.pod_id} (${(args.paths || []).length} graphs) approved by ${String(args.approved_by).trim()}`); return json(await runflows.run(args.pod_id, args.paths || [], { approvedBy: String(args.approved_by).trim() })) } },
    { name: 'pod_models', description: "Which VAE and diffusion model a pod's workflows use (ADR-042), and the files its ComfyUI offers for each (models/vae, models/diffusion_models on its volume; needs the pod running to list them). Give vae and/or diffusion_model to choose (an empty string clears it: the graph keeps its own); run_pod_workflows then puts the choice into each graph that has exactly one such loader, and names what it left alone. Our side only, no spend", inputSchema: obj({ pod_id: S('A pod'), vae: S('VAE file name, empty to clear'), diffusion_model: S('Diffusion model file name, empty to clear') }, ['pod_id']),
      run: async ({ pod_id, vae, diffusion_model }) => { try { if (vae !== undefined || diffusion_model !== undefined) runflows.setModels(pod_id, { ...(vae !== undefined ? { vae } : {}), ...(diffusion_model !== undefined ? { diffusion_model } : {}) }); return json(await runflows.models(pod_id)) } catch (e) { return text(e.message, true) } } },
    { name: 'run_workflows_job', description: "A failed graph carries `failure_text`, `recovery`, `retryable`, `missing_models` and `node_type` (the failure is also in failures.jsonl: see the `failures` tool). Where a run_pod_workflows job is: each graph waiting, running, done, failed (with the error) or skipped; cancel: true stops it (the running graph is interrupted). Give the job id, or pod_id for that pod's current run (the one still running, else the newest): what the Run workflows window shows again when it is reopened", inputSchema: obj({ id: S('Job id from run_pod_workflows'), pod_id: S("A pod: its current run, instead of an id"), cancel: B('Stop the job') }), run: async ({ id, pod_id, cancel }) => { if (!id && !pod_id) return text('Give id or pod_id', true); const j = id ? (cancel ? runflows.cancel(id) : runflows.job(id)) : runflows.latest(pod_id); const k = j && cancel && !id ? runflows.cancel(j.id) : j; return k ? json(k) : text(id ? `No such run: ${id}` : `No run on pod ${pod_id}`, true) } },
    { name: 'panama_place', description: "Put a round that a pod has pulled where its graphs look (ADR-033), on a running pod of yours: its inputs linked into input/rounds/<round>/ (and at the shipped path when free, a differing file is a conflict, never replaced), each loaded file also hard-linked at the top of input/ under a unique name (ComfyUI's dropdown lists only top-level files), and path-corrected copies of its graphs in workflows/rounds/<round>/ (the originals stay in the round folder, not in the panel). A pod pull does this by itself once its check passes; this is for a round pulled before, or to re-run. dry_run (default true) reads and reports, writes nothing. Idempotent",
      inputSchema: obj({ round: S('Round name'), pod_id: S('A running pod (default: the running pod of yours on the configured volume)'), dry_run: B('default true: report only') }, ['round']),
      run: async ({ round, pod_id, dry_run = true }) => json(await podpull.placeRound(round, { pod_id: pod_id || undefined, dry_run: dry_run !== false })) },
    { name: 'panama_import', description: "Import a downloaded round into ComfyUI-Shared (the window's Use): plans it through an adapter, and applies unless dry_run (default true). The round must be staged on this PC (panama_pull)", inputSchema: obj({ round: S('Round name'), adapter: S('Adapter id (default: the best match)'), dry_run: B('default true'), overwrite: B('Replace differing files') }, ['round']),
      run: async ({ round, adapter, dry_run = true, overwrite = false }) => {
        const dir = `${panama.stagingDir()}/${round}`
        if (!existsSync(dir)) return text(`${round} is not staged on this PC (${dir}): panama_pull it first`, true)
        const p = await imports.plan(dir, adapter || undefined)
        const r = await imports.apply(p, { dryRun: dry_run !== false, overwrite: !!overwrite })
        return json({ round, adapter: p.adapter, dry_run: r.dry_run, ok: r.ok, counts: r.counts, record: r.record, findings: p.findings, problems: r.results.filter((x) => ['conflict', 'hash-mismatch', 'error'].includes(x.status)).slice(0, 30) })
      } },

    // ---------- import: adapters, packages, zips ----------
    { name: 'import_detect', description: 'Which adapters recognise a package, best first, with a match score. The source is a folder or a .zip (unpacked once)', inputSchema: obj({ source: S('Absolute path of a folder or a .zip') }, ['source']),
      run: async ({ source }) => json(await imports.detect(imports.prepareSource(absolutePath(source, 'source')))) },
    { name: 'package_summary', description: "A package at a glance (the window's description input): file counts, folders, sample files. Folder or .zip", inputSchema: obj({ source: S('Absolute path of a folder or a .zip') }, ['source']),
      run: async ({ source }) => { const { _texts, ...rest } = imports.draftPreview(imports.prepareSource(absolutePath(source, 'source'))); return json(rest) } },
    { name: 'package_tree', description: "A package as a file tree (the Adapter Studio's explorer). Folder or .zip", inputSchema: obj({ source: S('Absolute path of a folder or a .zip') }, ['source']),
      run: async ({ source }) => json(studio.packageTree(imports.prepareSource(absolutePath(source, 'source')))) },
    { name: 'package_file', description: 'Read one file of a package, as the Adapter Studio shows it (text, or what it is). Folder or .zip', inputSchema: obj({ source: S('Absolute path of a folder or a .zip'), path: S('Path inside the package') }, ['source', 'path']),
      run: async ({ source, path }) => json(studio.readPackageFile(imports.prepareSource(absolutePath(source, 'source')), path)) },
    { name: 'package_describe', description: 'A written description of a package from Claude (needs the Anthropic key; sends file names and small text files to Anthropic). Folder or .zip', inputSchema: obj({ source: S('Absolute path of a folder or a .zip') }, ['source']),
      run: async ({ source }) => json(await imports.describe(imports.prepareSource(absolutePath(source, 'source')))) },
    { name: 'adapter_draft', description: 'Have Claude draft an adapter for a package (needs the Anthropic key). Returns the adapter, whether it is valid and the model; save it with adapter_save to keep a changed one', inputSchema: obj({ source: S('Absolute path of a folder or a .zip'), id: S('Adapter id to draft into (optional)') }, ['source']),
      run: async ({ source, id }) => json(await imports.draft(imports.prepareSource(absolutePath(source, 'source')), id ? { id } : {})) },
    { name: 'adapter_document', description: "Have Claude write the documentation header an adapter must carry (needs the Anthropic key). Returns the adapter with its header; the code is saved with it", inputSchema: obj({ id: S('Adapter id') }, ['id']),
      run: async ({ id }) => json(await studio.documentAdapter(id)) },
    { name: 'adapter_problems', description: "Check an adapter's code: its structure problems and, with a package, whether a test plan on it runs", inputSchema: obj({ id: S('Adapter id'), source: S('Absolute path of a package (folder or .zip) to test it on') }, ['id']),
      run: async ({ id, source }) => json(await studio.problems(id, source ? imports.prepareSource(absolutePath(source, 'source')) : null)) },
    { name: 'adapter_manage', description: "The adapters' housekeeping the Adapter Studio does: source (read the code), remove (a user's own, or reset a built-in override), template (a starter module), duplicate (from_id to id), get_prompt / save_prompt (the drafting prompt kept with it), rename (id and/or name), history (earlier versions), validate (check source text)",
      inputSchema: obj({ action: S('One of source, remove, template, duplicate, get_prompt, save_prompt, rename, history, validate', { enum: ['source', 'remove', 'template', 'duplicate', 'get_prompt', 'save_prompt', 'rename', 'history', 'validate'] }), id: S('Adapter id'), from_id: S('duplicate: the adapter to copy'), name: S('template / rename: a display name'), new_id: S('rename: the new id'), text: S('save_prompt / validate: the text') }, ['action']),
      run: async (a) => {
        switch (a.action) {
          case 'source': return json(imports.source(a.id))
          case 'remove': return json(imports.remove(a.id))
          case 'template': return text(imports.template(a.id, a.name || undefined))
          case 'duplicate': return json({ id: a.id, code: imports.duplicate(a.from_id, a.id) })
          case 'get_prompt': return text(imports.getPrompt(a.id))
          case 'save_prompt': return json(imports.savePrompt(a.id, a.text || ''))
          case 'rename': return json(await imports.rename(a.id, { id: a.new_id || undefined, name: a.name || undefined }))
          case 'history': return json(imports.history(a.id))
          case 'validate': return json({ problems: imports.validateSource(a.text || '', a.id || undefined) })
          default: return text(`Unknown action: ${a.action}`, true)
        }
      } },
    { name: 'sync_after', description: 'What to sync to a pod after an import (the follow-up the window offers): the folders and the pod, or why nothing', inputSchema: obj({ pod_id: S('Pod ID; omit for the running one') }), run: async ({ pod_id }) => json(imports.syncAfter(pod_id || null)) },

    // ---------- images, git, repositories, remote, MCP ----------
    { name: 'image_env', description: "The ENV and ARG lines of the pod image (or the repo's Dockerfile) the form can load as pod environment", inputSchema: obj({ source: S('"image" or "dockerfile"'), image: S('An image reference') }), run: async (a) => json(await images.env({ source: a.source, image: a.image })) },
    { name: 'image_dockerfile', description: 'The Dockerfile an image was built from (read from its registry), for the image menu', inputSchema: obj({ image: S('An image reference') }), run: async (a) => json(await images.dockerfile({ image: a.image })) },
    { name: 'git_accounts', description: 'The git accounts connected (GitHub etc.): list, disconnect one, or list its repositories (q filters). Connecting one is an OAuth round trip in a browser: the window', inputSchema: obj({ action: S('list, disconnect or repos', { enum: ['list', 'disconnect', 'repos'] }), id: S('Account id'), q: S('repos: a filter') }, ['action']),
      run: async (a) => { if (a.action === 'disconnect') { git.disconnect(a.id); return json({ disconnected: a.id }) } return json(a.action === 'repos' ? await git.listRepos(a.id, a.q || '') : git.listAccounts()) } },
    { name: 'repositories', description: 'The repositories attached to pods: list, add (url, branch), remove, search (GitHub), branches (of a url), folders (of a url and branch)', inputSchema: obj({ action: S('list, add, remove, search, branches, folders', { enum: ['list', 'add', 'remove', 'search', 'branches', 'folders'] }), url: S('Repository URL'), branch: S('Branch'), id: S('remove: repository id'), q: S('search: a query') }, ['action']),
      run: async (a) => {
        switch (a.action) {
          case 'list': return json(repositories.list())
          case 'add': return json(await repositories.add(a.url, a.branch || null))
          case 'remove': repositories.remove(a.id); return json({ removed: a.id })
          case 'search': return json(await repositories.search(a.q || ''))
          case 'branches': return json(await repositories.branches(a.url))
          case 'folders': return json(await repositories.folders(a.url, a.branch || 'main'))
          default: return text(`Unknown action: ${a.action}`, true)
        }
      } },
    { name: 'remote_mcp', description: "The MCP servers this app uses (BH's console): status, or check (ask it for its tools). Its key is a setting: set_settings panama_console_key", inputSchema: obj({ action: S('status or check', { enum: ['status', 'check'] }) }, ['action']),
      run: async ({ action }) => json(action === 'check' ? await remote.check() : remote.status()) },
    { name: 'mcp_endpoints', description: "The two MCP endpoints the app offers (this pod manager and the ComfyUI bridge) with their client configuration snippets, and what the bridge can point at. Serving them from the app and probing them is the window's Connect tab", inputSchema: obj({ comfy: S('A ComfyUI URL for the bridge snippet') }),
      run: async ({ comfy }) => json({ endpoints: mcp.endpoints({ comfy: comfy || null, served: {} }), targets: await mcp.targets() }) },

    // ---------- the README and the documentation ----------
    { name: 'docs', description: 'Our README, changelog and documentation (docs/*.md: the ADRs, setup, MCP, workflows). No arguments: the list. page: read one (README.md, docs/ADR-028-....md). search: matching lines across them. Not the client-job pages (the public docs site leaves those out too)',
      inputSchema: obj({ page: S('A page name from the list, or its docs:// uri'), search: S('Text to find') }),
      run: async ({ page, search }) => {
        if (!docs.root()) return plain('The documentation is not available here: it is read from the repository checkout (or COMFY_REPO_ROOT), and this server has none.', true)
        if (search) return plain({ query: search, matches: docs.search(search) })
        if (!page) return plain(docs.listing().map(({ name, title, bytes }) => ({ name, title, bytes })))
        const t = docs.read(page)
        return t == null ? plain(`No such page: ${page}. Pages: ${docs.listing().map((p) => p.name).join(', ')}`, true) : plain(t)
      } },
    // ---------- chunked runs (docs/CHUNKING.md) ----------
    { name: 'chunk_plan', description: "Split a frame range into chunks (docs/CHUNKING.md): a long shot loaded whole can fill a container's RAM and be OOM-killed (exit 137). Returns the ranges; with write_jobs, also writes one job file per chunk into queue/<project>/in/ (never queue/canalv2/). A graph with BincSeqToImage takes frame NUMBERS (the file names); one with only BH_ReadSequence takes INDEXES. No spend",
      inputSchema: obj({ first: N('First frame'), last: N('Last frame'), chunk: N(`Frames per chunk (default ${chunking.DEFAULT_CHUNK}; about 50 for 4K with SeedVR2 or LTX)`), write_jobs: obj({ project: S('queue/<project>/ folder, not canalv2'), shot: S('Shot name for the job files'), graph_path: S('The panel path the jobs run'), pod_id: S('A pod to name in the jobs') }, ['project', 'shot']) }, ['first', 'last']),
      run: async ({ first, last, chunk, write_jobs }) => {
        try {
          const chunks = chunking.plan(first, last, chunk ?? chunking.DEFAULT_CHUNK)
          if (!write_jobs) return json({ count: chunks.length, chunks })
          const w = chunking.writeJobFiles({ ...write_jobs, first, last, chunk })
          return json({ count: chunks.length, chunks, dir: w.dir, files: w.files })
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'run_shot_chunked', description: "Run a shot's graph on a running pod as consecutive frame ranges (docs/CHUNKING.md), so RAM never holds the whole sequence: each chunk sets BincSeqToImage first_frame/last_frame (or BH_ReadSequence first_index/count), runs, then ComfyUI is told to free memory. The RAM guard reads the pod's container memory over SSH while it runs: past ram_guard_pct (default 85) the chunk is interrupted and the job stops with the chunk and frames to resume from. Give the graph (API format) or a panel path. Locked shots are refused. Returns a job: follow it with chunked_job. Runs on a pod already billing: approved_by (only when the named-yes setting is on)",
      inputSchema: obj({ pod_id: S('A running pod'), path: S('Panel path from list_pod_workflows (a UI graph, converted like run_pod_workflows)'), graph: O('Or an API-format graph'), first: N('First frame (a frame number with BincSeqToImage, an index with BH_ReadSequence only)'), last: N('Last frame'), chunk: N(`Frames per chunk (default ${chunking.DEFAULT_CHUNK})`), ram_guard_pct: N(`Stop when the container passes this share of its RAM (default ${chunking.DEFAULT_RAM_GUARD_PCT})`), approved_by: approved.properties.approved_by }, ['pod_id', 'first', 'last']),
      run: async (args) => {
        const refusal = yes(args, 'run_shot_chunked'); if (refusal) return text(refusal, true)
        try {
          console.error(`run_shot_chunked on ${args.pod_id} frames ${args.first}-${args.last} approved by ${String(args.approved_by).trim()}`)
          return json(await chunking.run(args.pod_id, { path: args.path, graph: args.graph, first: args.first, last: args.last, chunk: args.chunk, ramGuardPct: args.ram_guard_pct, approvedBy: String(args.approved_by).trim() }))
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'chunked_job', description: 'A failed chunk carries `failure_text`, `recovery` and `retryable`. Where a run_shot_chunked job is: each chunk waiting, running, done or failed, the RAM now and its peak, and why it stopped (the RAM guard names the chunk and the frame to resume from); cancel: true interrupts the running chunk and skips the rest', inputSchema: obj({ id: S('Job id from run_shot_chunked'), cancel: B('Stop the job') }, ['id']),
      run: async ({ id, cancel }) => { try { const j = cancel ? chunking.cancel(id) : chunking.job(id); return j ? json(j) : text(`No such chunked run: ${id}`, true) } catch (e) { return text(e.message, true) } } },
    { name: 'pod_ram', description: "A pod's container memory right now, from its cgroup over SSH (the host's figure that ComfyUI's own /system_stats gives is not the container's limit): used, limit, percent, and whether it is over the guard's limit. null when the pod has no memory limit or cannot be reached. Read-only, no spend", inputSchema: obj({ pod_id: S('A running pod'), ram_guard_pct: N(`The limit to compare with (default ${chunking.DEFAULT_RAM_GUARD_PCT})`) }, ['pod_id']),
      run: async ({ pod_id, ram_guard_pct }) => { const r = await chunking.readRam(pod_id); const lim = ram_guard_pct ?? chunking.DEFAULT_RAM_GUARD_PCT; return json(r ? { ...r, used_gib: chunking.gib(r.used), limit_gib: chunking.gib(r.limit), ram_guard_pct: lim, over: chunking.overLimit(r, lim) } : { ram: null, note: 'No container memory limit found, or the pod could not be reached over SSH.' }) } },
    // ---------- retry later (ADR-042 section 19) ----------
    { name: 'pod_watch', description: "The Retry Later watches: what is waiting for RunPod to have a free card, started by resume_pod or create_pod with retry_until_free (or the window's Retry Later). action list (default): every watch with its kind (resume | create), state (waiting, done, stopped, expired, cancelled), tries, next try, last answer, give-up time and the pod it made; a create made like another pod (the window's 'Another GPU') also carries `from_pod_id`, the pod it was made from. With pod_id, list only the waits on that pod's card: its resume watch and the creates made like it (what the window shows under the pod). action cancel: stop one (id from the list, or the pod_id of a resume watch). Cancelling nothing deletes or resumes anything; a create cancelled while a try was in flight says to check the pod list. No spend",
      inputSchema: obj({ action: S('list (default) | cancel'), id: S('cancel: the watch id'), pod_id: S('list: only the waits on this pod\'s card; cancel: the pod whose resume watch to stop') }),
      run: async ({ action, id, pod_id }) => {
        try {
          if (action === 'cancel') { const w = pods.cancelWatch(String(id || pod_id || '')); return json({ cancelled: w.id, watch: w }) }
          if (action != null && action !== 'list') return text("action must be 'list' or 'cancel'", true)
          let all = pods.watches()
          if (pod_id) { let name = ''; try { name = (await pods.get(String(pod_id))).name || '' } catch { /* a pod that is gone: its waits still match by id */ } all = pods.watchesFor(String(pod_id), name) }
          return json({ waiting: all.filter((w) => w.state === 'waiting').length, watches: all })
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'pod_retry_options', description: "What the window's Retry Later popup offers for a pod that cannot resume because its host has no free GPU, in one answer: (1) same_gpu: wait for THIS pod's own host (resume_pod with retry_until_free: true; the pod is pinned to its host); (2) another_gpu: the cards its datacenter runs that the app can start, free ones first then cheapest, each with its key (use it as `gpu`), name, VRAM, price per hour and stock; start one with create_pod { like_pod_id, gpu, approved_by, retry_until_free: true } (or gpus: [several keys in your order of preference]: the first with a card free is used and ONE pod is made): a NEW pod like this one (same image, disk, network volume and configuration) in the same datacenter, this pod is NOT stopped or deleted. Also the waits already on this pod's card (the window allows one 'another GPU' wait per pod; cancel it with pod_watch). Read-only, no spend",
      inputSchema: obj({ pod_id: S('The pod (list_pods)') }, ['pod_id']),
      run: async ({ pod_id }) => {
        try {
          const p = await pods.get(String(pod_id))
          const dc = ((await pods.datacenters()).datacenters || []).find((d) => d.value === p.datacenter)
          const cards = (dc?.cards || []).filter((c) => c.runs !== false).slice().sort((a, b) => Number(b.available !== false) - Number(a.available !== false) || (a.price ?? 9e9) - (b.price ?? 9e9))
            .map((c) => ({ gpu: c.key, name: c.name, vram_gb: c.vram ?? null, price_per_hour: c.price ?? null, available: c.available !== false, stock: c.stock ?? null }))
          const waiting = pods.watchesFor(p.id, p.name).filter((w) => w.state === 'waiting')
          return json({
            pod: { id: p.id, name: p.name, gpu: p.gpu, datacenter: p.datacenter || null, status: p.status },
            same_gpu: { gpu: p.gpu, how: 'resume_pod { pod_id, retry_until_free: true }: resumes this pod when its own host has a free GPU' },
            another_gpu: { datacenter: p.datacenter || null, how: 'create_pod { like_pod_id, gpu: <a card key below> (or gpus: [keys in your order of preference]: the first free one is used, one pod is made), approved_by, retry_until_free: true }: makes a NEW pod like this one in the same datacenter when a card is free; this pod is not stopped or deleted', cards },
            waiting,
            ...(waiting.length ? { note: 'This pod already has a wait: cancel it with pod_watch { action: "cancel", id } before starting another one.' } : {}),
          })
        } catch (e) { return text(e.message, true) }
      } },
    // ---------- auto sync and the volume's change feed (docs/ADR-046) ----------
    { name: 'volume_changes', description: "The change feed of a network volume (docs/ADR-046): small events the app and its reconciler write under comfy-shared/.journal/ when files appear, change or go: { seq (the key), ts, writer (app:sync | app:pull | app:models | app:erase | reconciler | pod:<id>), op (created | modified | deleted | batch), prefix and/or path (and paths), files, bytes }. Paths are relative to comfy-shared/ (output/proxy_v004/...). Pass `since` = the `cursor` of the last answer to get only what is new (or 'now' for the end of the journal, or an ISO time); `prefix` narrows to a folder (output/); `limit` 1 to 500 (default 100). Oldest first; `more` says there is more after the cursor. Read-only, works with the pod stopped or none at all (RunPod's S3 API; needs the S3 keys), one listing, never a scan of the volume. volume_id defaults to the Shared volume, else the default one.",
      inputSchema: obj({ volume_id: S('The network volume (default: the Shared volume, else the default one)'), since: S("A cursor from an earlier call, an ISO time, or 'now'; empty starts at the beginning of the journal"), prefix: S('Only events that touch this folder, relative to comfy-shared (e.g. output/)'), limit: N('At most this many journal files (1 to 500, default 100)') }),
      run: async ({ volume_id, since, prefix, limit }) => {
        try { return json(await core.journal.list({ volume_id: String(volume_id || mounts.load().shared_volume_id || mounts.load().network_volume_id || ''), since, prefix, limit })) } catch (e) { return text(e.message, true) }
      } },
    { name: 'auto_sync', description: "Auto sync (docs/ADR-046): a pod pulls its volume's changes (ComfyUI's outputs first) to this PC by itself, and optionally pushes this PC's changes up. action get (pod_id): { enabled, pull, push, approved_by, approved_at } (defaults: off; Pull on, Push off). action set (pod_id, enabled, pull, push, approved_by): enabled: true REQUIRES approved_by, the name of who says yes (it moves data between machines and keeps doing so; recorded in the History); off needs nothing. action status: { paused, items: [{ pod_id, pod_name, state (idle | waiting | syncing | needs_approval | error | done), direction, files_done, files_total, bytes_done, bytes_total, rate_bps, streams, current, pending_bytes, summary, error, conflicts: [{ path, reason }] }] } as this process knows it (the app's own MCP shares the app's state; a stdio server does not run the timer). action pause (on: true | false): stop starting new auto pulls and pushes (a running one finishes). action sync_now (pod_id): reconcile the volume and pull for that pod now. action approve (pod_id, yes): a pull above 5 GB waits in needs_approval; yes pulls it, no skips it. action dismiss (pod_id): clear an error or a finished item. Additive and never deleting; a file changed on both sides is reported and skipped, never overwritten; the project tree and plates are never included.",
      inputSchema: obj({ action: S('get | set | status | pause | sync_now | approve | dismiss'), pod_id: S('The pod'), enabled: B('set: turn Auto sync on (needs approved_by) or off'), pull: B('set: pull the volume\'s changes to this PC (default on)'), push: B('set: push this PC\'s changes to the volume (default off)'), approved_by: S('set with enabled: true: the name of who says yes'), on: B('pause: true pauses, false resumes'), yes: B('approve: true pulls, false skips') }, ['action']),
      run: async ({ action, pod_id, enabled, pull, push, approved_by, on, yes }) => {
        try {
          const a = core.autosync
          const need = () => { if (!pod_id) throw Object.assign(new Error('pod_id is needed'), { status: 400 }); return String(pod_id) }
          switch (action) {
            case 'get': return json(a.get(need()))
            case 'set': return json(a.set(need(), { ...(enabled !== undefined ? { enabled } : {}), ...(pull !== undefined ? { pull } : {}), ...(push !== undefined ? { push } : {}), ...(approved_by !== undefined ? { approved_by } : {}) }))
            case 'status': return json(a.status())
            case 'pause': return json(a.pause(on !== false))
            case 'sync_now': return json(await a.syncNow(need()))
            case 'approve': return json(await a.approve(need(), yes === true))
            case 'dismiss': return json(a.dismiss(need()))
            default: return text("action must be get, set, status, pause, sync_now, approve or dismiss", true)
          }
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'sync_runs', description: "The sync explorer (docs/ADR-046): every sync run, a person's Sync and Auto sync's, with its log. action active (default): the runs in flight { run_id, pod_id, pod_name, direction, trigger (manual | auto-sync:output | auto-sync:feed | auto-sync:reconcile | auto-sync:push), state (queued | running), steps, files_done / files_total, bytes_done / bytes_total, rate_bps, eta_s, streams, current_files (the files in flight, at most 8: path, bytes, percent), recent_files (the last 20 finished) }. action recent (pod_id, limit): finished runs, newest first, with state, files, bytes, failed, warned, summary, error (kept across a restart). action log (run_id, offset, limit, level): a run's lines { ts, level, text, path } (the rsync / aws output, the plan, listing, totals and step events, problems, the summary); readable while the run runs; at most 5,000 lines per run (the first 500 and the last 4,500 with an 'n lines omitted' line), kept 14 days and 50 MB. action watch: what Auto sync's watchers do now: pull (per pod: state, cursor, last event, last and next reconcile, pending events / paths / bytes), push (per pod: folders watched and pending, debounce time left, last change and push), and the last 30 feed events. From this process's memory: the app's own MCP shares the app's runs; a stdio server sees only the runs it started. Read-only.",
      inputSchema: obj({ action: S('active (default) | recent | log | watch'), pod_id: S('recent: only this pod'), run_id: S('log: the run (from active or recent)'), limit: N('recent: how many (default 20); log: how many lines (default 500, at most 2000)'), offset: N('log: skip this many lines'), level: S('log: only this level and worse (info | warn | error)') }),
      run: async ({ action, pod_id, run_id, limit, offset, level }) => {
        try {
          const a = action ?? 'active', reg = core.syncruns.registry
          if (a === 'active') return json(reg.active())
          if (a === 'recent') return json({ runs: reg.recent(pod_id || undefined, limit) })
          if (a === 'log') { if (!run_id) return text('run_id is needed (sync_runs active or recent lists them)', true); return json(await reg.log(String(run_id), { offset, limit, level })) }
          if (a === 'watch') return json(core.autosync.watch())
          return text('action must be active, recent, log or watch', true)
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'render_sequences', description: "Render DPX sequences into mp4 for playback and review (docs/ADR-048). kind proxy (default): a quick-play H.264 kept at comfy-shared/output/.proxies/<dir>/<name>_<width>.mp4 (hidden) on the volume and pulled to this PC. kind review: the stitched review video DELIVERABLE, one full-length mono file per COMPLETE shot sequence in a visible versioned folder output/deliver/<shot>/v###/ (a new version every run, nothing overwritten) with <file>.meta.json and DELIVERY.md; needs approved_by (the named yes); never partial; ProRes 422 HQ .mov (the default, 10-bit 4:2:2, the conform file) and/or H.264 .mp4 (crf 14) (codecs). Files are named by the CLIP NAME (the EDL's; default the frames' stem, override per sequence with clip_name) so a conform relinks, in output/deliver/<shot>/v###/<clip>.mov|.mp4; the start timecode is read from the first frame's DPX header and embedded (never invented). The quick proxy is always H.264. Width: source (the frames' native size, e.g. 3840x2160, no scaling; the default) or 960, 1280, 1920. An incomplete sequence is refused (state incomplete, the missing ranges named) unless allow_partial (proxy only; written as _partial.mp4). Colour precedence: a stated colour_in (per run or per sequence) beats everything; then the colour record ComfyUI-OCIO writes next to each sequence (<dir>/<stem>.json, colorInteropID g26_p3d65_display = p3-d65-gamma26; stated by the writer, not guessed; the plan row says colour_source ocio-record, ocio {...}, and header_disagrees when the DPX header says something else: on this project the header is wrong, so the record wins); then render.colour.mode (format, ask, guess); last known. Without a record, a review is refused when the DPX header says log, linear or printing density (colour is stated, never guessed). The decoded frame count is verified against the expected. where: auto (default: the pod when it runs with SSH, else this PC), pod (needs pod_id) or local (this PC's ffmpeg on the synced frames, no pod). A sequence is { dir, name, first, last, frames, pad, fps?, clip_name? }; fps from the request, else the name (23.976 is sent as 24000/1001), else 24. Omitted width, where, kind, codecs, fps, pull come from the effective render settings (the pod's own configuration, else the Default Configuration). Sending to the client is Binc's; this app never sends. action plan: adapters (id, ok, reason, code no_ffmpeg | ffmpeg_broken, install_hint), settings, notes (a pod with fewer than 8 vCPUs warns for a 4K review; DPX decode and ffmpeg are CPU-bound, so a cheap card with many vCPUs is enough), pod_cpu { cores, mem_mb, free_gb }, estimate { output_gb } (ProRes 422 HQ at 4K is about 5.3 GB per minute of picture at 24 fps), per sequence complete, missing, source {width,height,bits}, estimate, where, out (review: shot, next_version); start: { job_id }; status (job_id?); cancel (job_id); proxies (pod_id?/volume_id?, items [{ dir, name }], width?): where each proxy is, complete/partial/fps/frames from its sidecar, and the review versions (deliverables). A missing local ffmpeg says: install it with Homebrew (brew install ffmpeg); nothing is ever installed.",
      inputSchema: obj({ colour_mode: S('plan, start: what to do with frames whose DPX header says log, linear or printing density when no colour_in is given, for THIS run (default: render.colour.mode of the configuration). ask: the sequence is skipped with a warning (not a failed job). format: convert from render.colour.format. guess: convert from the header (linear = Rec.709 primaries assumed, printing density = the Cineon reference, other log = tagged only) and say so in the sidecar, DELIVERY.md and the manifest (guessed: true). The Tunnel preset is STRICT: it never guesses (format counts as stated, ask keeps the block)'), colour_in: S('plan, start: what the DPX frames are, STATED by a person (policy/colour.md): p3-d65-gamma26 | p3-d65-srgb | p3-d65-gamma22 | kodak-log | linear-p3-d65 | linear-rec709; needed for frames whose header says log or linear (plan flag colour-not-stated); a sequence can carry its own colour_in'), preset: S('plan, start: none | tunnel (the Tunnel proxy: needs per-sequence colour_in, a start timecode from the field, the DPX header or the EDL; plan rows carry flags[], expected_frames, edl_element, suggested_colour)'), edl_override: { type: 'object', description: 'plan, start: sequence stem -> true to run it although its frame count differs from the EDL cut (recorded in the manifest notes)' }, skip_existing: B('plan, start: skip what is already done (default true): a proxy newer than its frames, a clip that already has a review version; start refuses with a 400 when everything is skipped. false renders again (a proxy replaces the old one atomically; a review makes a new version). Per run only.'), publish: { type: 'object', description: "start: publish the finished files once they are on this PC (docs/ADR-050): { targets: ['s3','slack'], message? }. Needs approved_by (also for a proxy); per run only, never a stored default.", properties: { targets: { type: 'array', items: S('s3 | slack') }, message: S('Slack message template') } }, action: S('plan | start | status | cancel | proxies'), pod_id: S('The pod (needed for where pod; optional for local)'), sequences: { type: 'array', items: { type: 'object', properties: { dir: S('Folder under output/'), name: S('File stem before the frame number'), first: N('First frame number'), last: N('Last frame number'), frames: N('How many frames are listed'), pad: N('Digits of the frame number'), fps: { type: 'number' }, clip_name: S('The EDL clip name the outputs carry (letters, digits, . _ - space; no uuid or hash); default the stem') }, required: ['dir', 'name', 'first', 'last', 'frames', 'pad'] }, description: 'The sequences (plan, start)' }, kind: S('proxy (default, from the settings) | review'), width: { anyOf: [{ type: 'string', enum: ['source'] }, { type: 'integer', enum: [960, 1280, 1920] }], description: 'source (native size, default) or 960, 1280, 1920' }, codecs: { type: 'array', items: { type: 'string', enum: ['h264', 'prores422hq'] }, description: 'review: prores422hq (default) and/or h264' }, approved_by: S('review: the name of who says yes (required)'), allow_partial: B('proxy: render the contiguous run of an incomplete sequence as a _partial file'), fps: { type: 'number', description: 'Frame rate for every sequence (default: from the name, else 24)' }, pull: B('start: pull the result to this PC after rendering on the pod (default from the settings, true)'), where: S('auto | pod | local (default from the settings)'), job_id: S('status, cancel'), items: { type: 'array', items: { type: 'object' }, description: 'proxies: [{ dir, name }]' }, volume_id: S('proxies: the volume (default the pod\'s, else the Shared one)') }, ['action']),
      run: async ({ action, pod_id, sequences, kind, width, codecs, approved_by, allow_partial, fps, pull, where, job_id, items, volume_id, publish, skip_existing, preset, edl_override, colour_in, colour_mode }) => {
        try {
          const r = core.renders
          if (action === 'plan') return json(await r.plan({ pod_id, sequences, kind, width, codecs, where, allow_partial, fps, ...(preset ? { preset } : {}), ...(edl_override ? { edl_override } : {}), ...(colour_in ? { colour_in } : {}), ...(colour_mode ? { colour_mode } : {}), ...(skip_existing !== undefined ? { skip_existing } : {}) }))
          if (action === 'start') return json(await r.start({ pod_id, sequences, kind, width, codecs, approved_by, allow_partial, fps, pull, where, ...(preset ? { preset } : {}), ...(edl_override ? { edl_override } : {}), ...(colour_in ? { colour_in } : {}), ...(colour_mode ? { colour_mode } : {}), ...(skip_existing !== undefined ? { skip_existing } : {}), ...(publish ? { publish } : {}) }))
          if (action === 'status') return json(r.status(job_id))
          if (action === 'cancel') { if (!job_id) return text('job_id is needed', true); return json(r.cancel(String(job_id))) }
          if (action === 'proxies') return json(await r.proxies({ pod_id, volume_id, items, width }))
          return text('action must be plan, start, status, cancel or proxies', true)
        } catch (e) { return text(`${e.message}${e.code ? ` [${e.code}]` : ''}`, true) }
      } },
    { name: 'app_logs', description: "The application's own log, kept: everything the app's main process prints (console), the window's page warnings and errors, unhandled errors and crashes, one line each (`time LEVEL text`) in app-logs/<day>.log in the config folder, secrets cut out. action list: the days, newest first, with their size. read (name = a day from list, level? all | warn | error, match? text, tail? lines): the lines. purge (name?, confirmed): DELETE one day's log or all of them: ask the user first, then confirmed: true; never on your own. Nothing else ever deletes an app log", inputSchema: obj({ action: S('list | read | purge'), name: S('read, purge: YYYY-MM-DD.log from list'), level: S('read: all (default) | warn | error'), match: S('read: only lines containing this text'), tail: N('read: only the last N lines (default 300)'), confirmed: B('purge: true only after the user said yes') }, ['action']),
      run: async ({ action, name, level, match, tail, confirmed }) => { try { if (action === 'purge') return json(await core.applogs.purge({ name, confirmed })); if (action === 'read') return json(await core.applogs.read(name, { level, match, tail })); if (action === 'list' || !action) return json(await core.applogs.list()); return text('action is list, read or purge', true) } catch (e) { return text(e.message, true) } } },
    { name: 'pod_logs', description: "Pod logs, kept: a pod's logs go when the pod is deleted, so the app writes them to a file (pod-logs/<day>/<pod name>_<pod id>_<time>.log in its config folder) at the end of each run task and just before it deletes a pod; nothing here ever deletes a log. action save (pod_id): write the logs of a running or stopped pod now, the RunPod container and system log and ComfyUI's server log -> { name, path, bytes, lines }. list (pod_id?): the saved logs, newest first. read (name, tail?): one saved log's text, whole or its last `tail` lines. purge (pod_id? , confirmed): DELETE the saved logs of one pod or of all pods: ask the user first, then confirmed: true; never on your own. Otherwise read-only apart from the new file", inputSchema: obj({ action: S('save | list | read'), pod_id: S('save: the pod; list: only that pod'), name: S('read: day/file.log from list'), tail: N('read: only the last N lines'), confirmed: B('purge: true only after the user said yes') }, ['action']),
      run: async ({ action, pod_id, name, tail, confirmed }) => { try { if (action === 'purge') return json(await core.podlogs.purge({ pod_id, confirmed })); if (action === 'save') return json(await core.podlogs.save(pod_id, { reason: 'asked for through MCP' })); if (action === 'read') return json(await core.podlogs.read(name, { tail })); if (action === 'list' || !action) return json(await core.podlogs.list({ pod_id })); return text('action is save, list, read or purge', true) } catch (e) { return text(e.message, true) } } },
    { name: 'dpx_make', description: "Unpack a master video into a 16-bit DPX sequence (Tunnel V11, docs/CANALV2-TUNNEL-V11-PRODUCTION-PLAN.md section 12 step 2; ADR-055), for elements that exist only as a ProRes .mov / .mp4. action plan (items: [{ master, shot, element, frames_expected? }], round default mono_v019): read-only, the folder and file names each item would write. action run (pod_id, items: [{ master, shot, element, frames_expected?, fps? }], round, approved_by): on a RUNNING pod that has the volume, ffmpeg writes <round>/<shot>/<shot>_<element>/dpx/<shot>_<element>_<round>_NOT_RELEASED.NNNN.dpx under comfy-shared/output/, 16-bit, numbered from 0000. master is a path relative to comfy-shared/ (e.g. temp/rounds/mono_v019/<shot>/approved/05-outputs/Approved/master/<file>.mov). It unpacks STRAIGHT: no conversion of primaries or gamma, only the YCbCr to RGB matrix from the master's tag (bt709 when untagged; the result says tagged: false) and the range expanded to full. It NEVER overwrites: a dpx folder that already holds files fails that item and nothing is written; frames go to a temporary sibling folder that is renamed into place only when the frame count equals frames_expected (when given) and the first frame reads 16-bit. Each item is its own result { shot, element, frames, expected, ok, out_dir, colour, error? }; a failure stops that item only. An EDL element is a CUT of its master: source_ranges [{ in, out }] (HH:MM:SS:FF, in inclusive, out EXCLUSIVE, ascending, at most 20) unpacks only those frames, in order, into one sequence from 0000 (the count must equal their sum and frames_expected); start_timecode_of_master (default: the master's own timecode tag, else 00:00:00:00); plan shows the master frame numbers each range maps to; from_edl: true (with shot and element) fills frames_expected, source_ranges and fps from the loaded EDL (load it first; a retimed element is refused). Without source_ranges the whole master is unpacked. run needs approved_by and spends only pod time", inputSchema: obj({ action: S('plan | run (default run)'), pod_id: S('run: a running pod that has the volume'), round: S('Round name for the output folder (default mono_v019)'), items: { type: 'array', description: '[{ master (path under comfy-shared/, .mov/.mp4/.mxf), shot, element, frames_expected?, fps?, source_ranges?, start_timecode_of_master?, from_edl? }]', items: { type: 'object' } }, approved_by: S('run: who says yes') }, ['items']),
      run: async ({ action, pod_id, items, round, approved_by }) => { try { if (action === 'plan') return json(await core.dpxmake.plan({ items, round })); return json(await core.dpxmake.run({ pod_id, items, round, approved_by })) } catch (e) { return text(e.message, true) } } },
    { name: 'dpx_fix', description:"Prepare For Delivery (Tunnel V11, docs/CANALV2-TUNNEL-V11-PRODUCTION-PLAN.md section 9; ADR-055): corrected COPIES of DPX sequences, the way the Outputs window's button does it. action plan (items: [{ src_dir, stem? }], src_dir = the frames folder under output/ on the volume, e.g. mono_v015/archival-077/archival-077_a/dpx): read-only, what each sequence would be delivered as -> rows { clip (the EDL's name, '' if it is not in the EDL), frames, expected_frames, start_timecode, fps, ok, why }. action run (pod_id, items: [{ src_dir, clip, start_timecode, fps? }], approved_by): on a RUNNING pod that has the volume, each frame is copied to comfy-shared/output/_delivery_v11/<clip>/<clip>.NNNN.dpx with its 2048-byte header corrected (colour code user-defined instead of linear, the per-frame timecode from start_timecode, the frame rate, gamma 2.6, the frame position) and the picture bytes copied unchanged; every header is read back and checked. The original frames are never touched. run needs approved_by and spends only pod time. Then publish the _delivery_v11/<clip> folders (publish run, items { where: 'volume', path: '_delivery_v11/<clip>' })", inputSchema: obj({ action: S('plan | run (default run)'), pod_id: S('run: a running pod that has the volume'), items: { type: 'array', description: 'plan: [{ src_dir, stem? }]; run: [{ src_dir, clip, start_timecode (HH:MM:SS:FF), fps (default 23.976) }]', items: { type: 'object' } }, approved_by: S('run: who says yes') }, ['items']),
      run: async ({ action, pod_id, items, approved_by }) => { try { if (action === 'plan') return json(await core.dpxfix.plan({ items })); return json(await core.dpxfix.run({ pod_id, items, approved_by })) } catch (e) { return text(e.message, true) } } },
    { name: 'publish', description: "Publish finished outputs to S3 and announce them in Slack (docs/ADR-050). Files leave this PC, so it is always a person's act: `run` needs approved_by (the name of who says yes) AND confirm: true, else you get the plan back and nothing is sent. The destination (bucket, prefix, webhook, channel) is entered by a person in Settings; an agent cannot set it, and nothing is configured by default. Model weights are never published. action settings: the masked settings (secrets never returned, only a hint; s3.transfer = auto | pod | pc says how volume files travel, set only by a person in Settings) and whether S3 and Slack are ready. local (dir?): one level of the local ComfyUI-Shared output/ tree { entries: [{ name, path, dir, bytes, modified, weight }] }. volume (dir?): the same for the volume's comfy-shared/output/ over RunPod's S3 API (folders carry `empty` when known). volume_size (path): files and bytes under one volume folder. Items may be a string (a path under this PC's output/) or { where: 'volume', path }; volume items go from a running pod on the volume when s3.transfer allows and one is available, else are streamed through this PC (status jobs carry adapter 'pod' | 'pc', pod, and per-file adapter and sha256). plan (items: paths under output/, files or folders; targets: s3 and/or slack; message?): { ok, blockers, items, total_bytes, files, s3: { dest, count, new_bytes }, slack: { to, preview }, refused } (same-size objects already there are skipped). run (items, targets, approved_by, confirm: true, message?): starts the upload then ONE Slack post when every upload succeeded -> { job_id }. status (job_id?): { jobs: [{ state, files_done, files_total, bytes_done, rate_bps, links, slack, summary }] }. cancel (job_id or a shot's child id). status shows `children` (one per shot: state, files, bytes, rate, error). rounds: the rounds already in the destination (BKK return). retry (child_id, approved_by, confirm: true): one failed shot again, alone. slack (job_id, approved_by, confirm: true): post the Slack message of a finished job again after a failure. backfill (ADR-050): step scan (sources) reads what the outputs hold (read-only) -> { job_id }; inventory (job_id) -> rows by shot with kind, frames, bytes, where (pc/volume) and in_destination; plan (rows or all) -> the keys under the destination with ORIGINAL names; run (approved_by + confirm: true) uploads them (files only on the volume are streamed through this PC) and writes _inventory_<date>.csv next to them.",
      inputSchema: obj({ action: S('settings | local | volume | volume_size | rounds | plan | run | retry | status | cancel | slack | backfill'), edl_override: { type: 'object', description: 'plan, run (bkk-return): sequence stem -> true to deliver it although its frame count differs from the EDL cut (recorded in the manifest notes); a sequence that is not in the EDL is never overridable. The plan returns sequences[] with flags[], expected_frames, edl_element.' }, start_timecodes: { type: 'object', description: 'plan, run (bkk-return): sequence stem -> HH:MM:SS:FF; else the DPX header, else the EDL source-in; with none the sequence is held back (flag no-start-timecode)' }, round: S('plan, run, backfill: the BKK return round (a folder under the prefix), like qc_2026-11-02_r01; required for the bkk-return layout'), clip_names: { type: 'object', description: 'plan, run: sequence stem -> the clip name it is delivered as (frames on disk are never renamed)', additionalProperties: S('clip name') }, streams: N('run: how many shots upload at once (default 1)'), child_id: S('retry: a failed shot (status lists `children`)'), path: S('volume_size: a folder under the volume output/'), step: S('backfill: scan | inventory | plan | run'), sources: { type: 'array', items: S('local-output | volume-output | volume-pipe-finals | volume-deliveries'), description: 'backfill scan: the places to read' }, rows: { type: 'array', items: S('An inventory row id'), description: 'backfill plan, run: which rows' }, all: B('backfill plan, run: every row except model weights'), destination_prefix: S('backfill plan, run: another prefix than the setting'), dir: S('local: a folder under output/ (default the top)'), items: { type: 'array', items: { anyOf: [S('A path relative to the local output/'), { type: 'object', properties: { where: S('volume'), path: S("A path relative to the volume's comfy-shared/output/") }, required: ['where', 'path'] }] }, description: "plan, run: files or folders: a string is a path under this PC's output/; { where: 'volume', path } is under the volume's output/ and is streamed through this PC (no local copy)" }, targets: { type: 'array', items: S('s3 | slack'), description: 'plan, run: where to publish' }, message: S('plan, run: the Slack message template ({approved_by} {count} {size} {dest} {files} {links} {date})'), approved_by: S('run, slack: the name of who says yes'), allow_overwrite: B('plan, run: true to write over files already in a delivery round (not _TEST_) that have another size; default false, the guard of ADR-055 section 1; only on Lucas\'s say'), preview_frame: B('plan, run, backfill: a first-frame preview in the Slack post for this run (default: the setting)'), confirm: B('run, slack: true to really send (without it only the plan is returned)'), job_id: S('status, cancel, slack') }, ['action']),
      run: async ({ action, path, dir, items, targets, message, approved_by, confirm, job_id, step, sources, rows, all, destination_prefix, preview_frame, allow_overwrite, round, clip_names, streams, child_id, edl_override, start_timecodes }) => {
        try {
          const p = core.publish
          const req = { items, targets, ...(allow_overwrite === true ? { allow_overwrite: true } : {}), ...(edl_override ? { edl_override } : {}), ...(start_timecodes ? { start_timecodes } : {}), ...(round ? { round } : {}), ...(clip_names ? { clip_names } : {}), ...(streams ? { streams } : {}), ...(message ? { message } : {}), ...(approved_by ? { approved_by } : {}), ...(preview_frame !== undefined ? { preview_frame } : {}) }
          switch (action) {
            case 'settings': return json(await p.settings())
            case 'local': return json(await p.local({ dir: dir || '' }))
            case 'volume': return json(await p.volume({ dir: dir || '' }))
            case 'rounds': return json(await p.rounds())
            case 'retry':
              if (!child_id) return text('child_id is needed (status lists the shots of a run)', true)
              if (!String(approved_by || '').trim() || confirm !== true) return json({ sent: false, not_run: 'Nothing was sent. Trying a shot again needs approved_by and confirm: true.' })
              return json(await p.retry({ child_id: String(child_id) }))
            case 'volume_size': return json(await p.volumeSize({ path }))
            case 'plan': return json(await p.plan(req))
            case 'run': {
              if (!String(approved_by || '').trim() || confirm !== true) return json({ sent: false, not_run: 'Nothing was sent. Publishing needs approved_by (the name of who says yes) and confirm: true, after the person has seen this plan.', plan: await p.plan(req) })
              return json(await p.run(req))
            }
            case 'status': return json(p.status(job_id || undefined))
            case 'cancel': if (!job_id) return text('job_id is needed', true); return json(p.cancel(String(job_id)))
            case 'backfill': {
              const b = { job_id, rows, all, targets, ...(round ? { round } : {}), ...(clip_names ? { clip_names } : {}), ...(preview_frame !== undefined ? { preview_frame } : {}), ...(destination_prefix ? { destination_prefix } : {}), ...(message ? { message } : {}), ...(approved_by ? { approved_by } : {}) }
              if (step === 'scan') return json(await p.scan({ sources }))
              if (step === 'inventory') return json(p.inventory(job_id || undefined))
              if (step === 'plan') return json(await p.backfillPlan(b))
              if (step === 'run') {
                if (!String(approved_by || '').trim() || confirm !== true) return json({ sent: false, not_run: 'Nothing was sent. Publishing needs approved_by (the name of who says yes) and confirm: true, after the person has seen this plan.', plan: await p.backfillPlan(b) })
                return json(await p.backfillRun(b))
              }
              return text('step must be scan, inventory, plan or run', true)
            }
            case 'slack':
              if (!job_id) return text('job_id is needed', true)
              if (!String(approved_by || '').trim() || confirm !== true) return json({ sent: false, not_run: 'Nothing was posted. Posting to Slack needs approved_by and confirm: true.' })
              return json(await p.slack({ job_id: String(job_id) }))
            default: return text('action must be settings, local, volume, volume_size, rounds, plan, retry, run, status, cancel, slack or backfill', true)
          }
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'running_jobs', description: "Jobs that OTHER processes are running right now (the stdio MCP server, a script, the app), from the shared running-jobs file in the config folder: id, kind (render, publish, volume, sync), trigger, origin (window, mcp, auto-publish, script), mcp_client, label, state, progress, started_at, heartbeat_at, pid. A job whose owner died is listed once as interrupted. READ-ONLY (cancelling is the window's).",
      inputSchema: obj({ kind: S('render | publish | volume | sync (default all)') }, []),
      run: async ({ kind }) => { try { await core.jobsregistry.refresh(); return json({ jobs: core.jobsregistry.externals(kind || undefined) }) } catch (e) { return text(e.message, true) } } },
    { name: 'failures', description: "Graph failures, logged: every graph that failed to load, validate, queue or execute on a pod, one record each (time, job_id, round, shot, graph, graph_version, pod_id, pod_name, gpu, stage load|validate|queue|execute|encode|transfer, node_id, node_type, message, log_tail, missing_models [{name, where_on_volume}], recovery, retryable, attempt), newest first, read from failures.jsonl in the config folder. READ-ONLY. Filters: limit (default 50), since (ISO time), shot, job_id.",
      inputSchema: obj({ limit: { type: 'number', description: 'at most this many (default 50, max 500)' }, since: S('only records at or after this ISO time'), shot: S('only this shot'), job_id: S('only this job') }, []),
      run: async ({ limit, since, shot, job_id }) => { try { const r = await core.failures.list({ ...(limit ? { limit: Number(limit) } : {}), ...(since ? { since: String(since) } : {}), ...(shot ? { shot: String(shot) } : {}), ...(job_id ? { job_id: String(job_id) } : {}) }); return json({ count: r.failures.length, file: r.file, failures: r.failures }) } catch (e) { return text(e.message, true) } } },
    { name: 'generate_existing', description: "Auto-generate for what is already there (docs/ADR-050): PREVIEW only. Lists the existing DPX sequences that would be rendered (settled, named, not weights, EDL flags clear, within the daily allowance) and those skipped with the reason; nothing starts. Starting them is confirmed in the window only.",
      inputSchema: obj({ dry_run: B('always a preview here'), confirm: B('refused: only the window confirms'), approved_by: S('ignored'), limit: { type: 'number', description: 'at most this many sequences' } }, []),
      run: async ({ confirm, limit }) => { try { if (confirm) return text('403: Only the window confirms', true); return json(await core.autopublish.generateExisting({ dry_run: true, ...(limit ? { limit: Number(limit) } : {}) })) } catch (e) { return text(e.message, true) } } },
    { name: 'edl', description: "The V11 edit list (docs/ADR-050, 'The EDL decides timecode, frame count and what may be delivered'): a CMX3600 parsed into elements (a clip name; its shot, element, version, raster, first source-in, frames in the cut, speeds, effects). READ-ONLY: `load` fetches the list from the exchange bucket (or the configured edl.source) and caches it with its sha256; `status` says what is loaded; `elements` lists them; `lookup` finds one by clip name, or shot and element (ambiguous when two match).",
      inputSchema: obj({ action: S('status | load | elements | lookup'), clip: S('lookup: the clip name (no extension needed)'), shot: S('lookup: for example enhance-146'), element: S('lookup: for example b or breach-alt1') }, ['action']),
      run: async ({ action, clip, shot, element }) => {
        try {
          await core.edl.ensure()
          switch (action) {
            case 'status': return json(core.edl.status())
            case 'load': return json(await core.edl.load({}))
            case 'elements': return json({ status: core.edl.status(), elements: core.edl.elements() })
            case 'lookup': return json(core.edl.lookup({ ...(clip ? { clip: String(clip) } : {}), ...(shot ? { shot: String(shot) } : {}), ...(element ? { element: String(element) } : {}) }))
            default: return text('action must be status, load, elements or lookup', true)
          }
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'autopublish', description: "Auto-publish (docs/ADR-050): approved, finished review videos are uploaded to the publish destination by themselves under a person's standing approval; off by default, dry-run first, with a cancel window and a daily cap. An agent may READ, CANCEL, switch it OFF, and (since v1.6.8) switch it ON and GO LIVE, always under the NAME of a person: enable and go_live need approved_by (never invented) and understood: true, the same two things the window asks for; enable starts in dry run unless dry_run_first is off, go_live needs the standing approval first. Approving or revoking a shot version, choosing where it sends (targets), releasing a hold and Publish now stay a person's acts in the window (they answer 403 here). action status: { enabled, dry_run, standing, window_minutes, daily_cap, today: { count, left }, destination, pending: [{ id, shot, version, files, bytes, due_at, state, reason? }], recent }. settings: the settings and whether the destination is ready. approvals: [{ shot, version, approved_by, at }]. reviews: the review versions on this PC with their approval and auto-publish state. cancel (id): cancel a waiting entry. off: stop the rule at once and cancel everything pending. scan_volume: list the volume's deliver/ now for finished reviews (read-only; what Auto-publish watches is `sources` in the configuration, `status.watching` says what it sees).",
      inputSchema: obj({ action: S('status | settings | approvals | reviews | cancel | off | scan_volume | enable | go_live | set_settings'), id: S('cancel: the pending entry id (from status)'), shot: S('hold: the shot'), version: S('hold: the version, like v002'), approved_by: S('enable, go_live, set_settings: the NAME of the person who allows Auto-publish (never guessed or invented); it becomes the standing approval'), understood: { type: 'boolean', description: 'enable, go_live: true when that person has been told that Auto-publish uploads approved review videos by itself under their name (the window asks the same)' }, settings: { type: 'object', description: 'enable, set_settings: window_minutes, daily_cap, include_dpx, require_approval, dry_run_first, round, sources, generate (not targets: where it sends is chosen in the window)' } }, ['action']),
      run: async ({ action, id, shot, version, approved_by, understood, settings }) => {
        try {
          const a = core.autopublish
          switch (action) {
            case 'status': return json(await a.statusNow())
            case 'settings': return json(await a.settings())
            case 'approvals': return json(await a.approvals())
            case 'reviews': return json(await a.reviews())
            case 'cancel': if (!id) return text('id is needed (status lists the pending entries)', true); return json(await a.cancel({ id: String(id) }))
            case 'off': return json(await a.offCount())
            case 'holds': return json(await a.holds())
            case 'dry_run_report': return json(await a.dryRunReport())   // preview only: posts nothing
            case 'hold': if (!shot || !version) return text('shot and version are needed', true); return json(await a.hold({ shot, version }))
            case 'release': return text("403: Only the window releases a hold", true)
            case 'scan_volume': return json(await a.scanVolume())
            case 'approve': case 'revoke': return text("403: Approval is a person's act: use the window", true)
            case 'set_targets': case 'targets': return text('403: Where Auto-publish sends is chosen in the window, by a person', true)
            case 'enable': case 'go_live': case 'set_settings': {   // Lucas, 2026-11-20: an agent may switch Auto-publish on and go live, always under the NAME of a person (approved_by) and with `understood: true`, the same two things the window asks for
              const name = String(approved_by ?? '').trim()
              if (!name) return text("approved_by is needed: the name of the person who allows Auto-publish (an agent never invents it)", true)
              const v = settings && typeof settings === 'object' && !Array.isArray(settings) ? { ...settings } : {}
              if ('targets' in v || 'tunnel' in v) return text('403: Where Auto-publish sends is chosen in the window, by a person', true)
              if (action === 'enable') v.enabled = true
              if (action === 'go_live') v.dry_run = false
              return json(await a.setSettings({ ...v, approved_by: name, understood: understood === true }))
            }
            case 'publish_now': return text("403: Publish now is a person's explicit, named click: use the window", true)
            default: return text('action must be status, settings, approvals, reviews, cancel, off, scan_volume, enable, go_live or set_settings', true)
          }
        } catch (e) { return text(e.message, true) }
      } },
    { name: 'sync_folders', description: "The folders a push could leave out (docs/ADR-011): for each push step (in the order a push runs them: workflows, comfy-shared, project, plates) the TOP-LEVEL directories of its local root on this PC, sorted, at most 500 (dotfiles and what a sync never carries are hidden): { steps: [{ key, local, folders: [{ name, bytes: null }] }] }. With measure: { step, name } it sizes ONE of them (`du -sk`, up to 120 s, cached 5 minutes): { bytes }. The name must be a direct child directory of that step's local root. Each step also carries `saved` (the patterns already saved for it: the global sync_exclude and the folder's own, de-duplicated) and `saved_sources`; `supports` says which features this core has. Use the result as `exclude` of sync (e.g. `/CANALV2/`). Read-only.",
      inputSchema: obj({ pod_id: S('The pod (its own configuration decides which folders are mapped)'), measure: { type: 'object', properties: { step: S('A step key from the list'), name: S('A folder name from the list') }, description: 'Size one folder instead of listing' } }, ['pod_id']),
      run: async ({ pod_id, measure }) => { try { if (measure) return json(await core.syncfolders.measure({ pod_id, step: measure.step, name: measure.name })); return json(await core.syncfolders.folders({ pod_id })) } catch (e) { return text(e.message, true) } } },
  ]

  const readJsonFile = (file) => {
    absolutePath(file, 'file')
    if (!existsSync(file) || !statSync(file).isFile()) throw Object.assign(new Error(`not a file: ${file}`), { status: 400 })
    if (statSync(file).size > MAX_FILE) throw Object.assign(new Error('That is not a configuration file (too large)'), { status: 400 })
    try { return JSON.parse(readFileSync(file, 'utf8')) } catch (e) { throw Object.assign(new Error(`not valid JSON: ${e.message}`), { status: 400 }) }
  }

  return { tools: T.map(({ run, ...def }) => def), handlers: Object.fromEntries(T.map((t) => [t.name, t.run])) }
}
